UPDATE question_options o SET text_es = v.text_es
FROM (VALUES
    ('What is the Event Loop?', 'A mechanism that takes callbacks from the task queues and runs them on the single JS thread whenever the call stack is empty', 'Un mecanismo que toma callbacks de las colas de tareas y los ejecuta en el único hilo de JS cada vez que la call stack está vacía'),
    ('What is the Event Loop?', 'A pool of threads that runs every JavaScript function in parallel', 'Un pool de hilos que ejecuta cada función JavaScript en paralelo'),
    ('What is the Event Loop?', 'A loop that re-renders the DOM 60 times per second', 'Un bucle que vuelve a renderizar el DOM 60 veces por segundo'),
    ('Explain closures', 'A function that keeps access to the variables of the scope where it was defined, even after that scope has returned', 'Una función que mantiene acceso a las variables del ámbito donde fue definida, incluso después de que ese ámbito haya terminado'),
    ('Explain closures', 'A function that is automatically closed and garbage-collected after its first call', 'Una función que se cierra automáticamente y es eliminada por el recolector de basura tras su primera llamada'),
    ('Explain closures', 'A way to make object properties private using the # prefix', 'Una forma de hacer privadas las propiedades de un objeto usando el prefijo #'),
    ('What is a Promise?', 'An object representing the eventual completion or failure of an async operation, consumed with then/catch or await', 'Un objeto que representa la finalización o el fallo eventual de una operación asíncrona, que se consume con then/catch o await'),
    ('What is a Promise?', 'A function that blocks the thread until an async operation finishes', 'Una función que bloquea el hilo hasta que termina una operación asíncrona'),
    ('What is a Promise?', 'A special kind of callback that can only be called synchronously', 'Un tipo especial de callback que solo puede llamarse de forma síncrona'),
    ('Explain the microtask vs macrotask queue', 'Microtasks (Promise callbacks, queueMicrotask) run right after the current task and before the next macrotask (setTimeout, I/O)', 'Las microtasks (callbacks de Promise, queueMicrotask) se ejecutan justo después de la tarea actual y antes de la siguiente macrotask (setTimeout, I/O)'),
    ('Explain the microtask vs macrotask queue', 'Macrotasks always run before any pending microtask', 'Las macrotasks siempre se ejecutan antes que cualquier microtask pendiente'),
    ('Explain the microtask vs macrotask queue', 'Both queues are processed in parallel on different threads', 'Ambas colas se procesan en paralelo en hilos distintos'),
    ('What is the Proxy object?', 'An object that wraps a target and intercepts operations like get, set or delete through handler traps (used in Vue 3 reactivity)', 'Un objeto que envuelve un target e intercepta operaciones como get, set o delete mediante handler traps (usado en la reactividad de Vue 3)'),
    ('What is the Proxy object?', 'An HTTP proxy built into the browser for fetch requests', 'Un proxy HTTP integrado en el navegador para las peticiones fetch'),
    ('What is the Proxy object?', 'A deep clone of an object that cannot be modified', 'Un clon profundo de un objeto que no se puede modificar'),
    ('Memory leaks in JavaScript', 'Forgotten timers, detached DOM nodes, lingering event listeners and unbounded caches; detected with heap snapshots in DevTools', 'Temporizadores olvidados, nodos del DOM desconectados, listeners de eventos que persisten y cachés sin límite; se detectan con heap snapshots en DevTools'),
    ('Memory leaks in JavaScript', 'They cannot happen because JavaScript has a garbage collector', 'No pueden ocurrir porque JavaScript tiene un recolector de basura'),
    ('Memory leaks in JavaScript', 'They only happen when using var instead of let', 'Solo ocurren cuando se usa var en lugar de let'),
    ('Generator functions and iterators', 'function* returns an iterator; yield pauses execution and next() resumes it, and async generators work with for await', 'function* devuelve un iterador; yield pausa la ejecución y next() la reanuda, y los generadores asíncronos funcionan con for await'),
    ('Generator functions and iterators', 'Generators are functions that run on a separate thread', 'Los generadores son funciones que se ejecutan en un hilo separado'),
    ('Generator functions and iterators', 'Generators automatically generate random values', 'Los generadores generan valores aleatorios automáticamente'),
    ('Event delegation and bubbling', 'Events bubble up from the target to ancestors, so one listener on a parent can handle events from many children', 'Los eventos suben (bubble) desde el elemento objetivo hacia sus ancestros, así que un único listener en el padre puede gestionar eventos de muchos hijos'),
    ('Event delegation and bubbling', 'Events travel only downward from the document to the target', 'Los eventos solo viajan hacia abajo, desde el document hasta el elemento objetivo'),
    ('Event delegation and bubbling', 'Each child element must have its own listener for events to work', 'Cada elemento hijo debe tener su propio listener para que los eventos funcionen'),
    ('map, filter and reduce', 'map transforms each element into a new array of the same length; filter keeps elements matching a condition; reduce folds the array into a single accumulated value.', 'map transforma cada elemento en un nuevo array de la misma longitud; filter conserva los elementos que cumplen una condición; reduce reduce el array a un único valor acumulado.'),
    ('map, filter and reduce', 'They are aliases for the same operation with different names.', 'Son alias de la misma operación con nombres distintos.'),
    ('map, filter and reduce', 'map and filter mutate the original array, reduce does not.', 'map y filter mutan el array original, reduce no.'),
    ('== vs ===', '== compares values after type coercion, while === compares both value and type without coercion.', '== compara los valores después de la coerción de tipos, mientras que === compara valor y tipo sin coerción.'),
    ('== vs ===', '=== is only used for comparing objects, == for primitives.', '=== solo se usa para comparar objetos, == para primitivos.'),
    ('== vs ===', 'There is no difference, they behave identically in modern JavaScript.', 'No hay diferencia, se comportan igual en el JavaScript moderno.'),
    ('Hoisting', 'Variable and function declarations are moved to the top of their scope during compilation, so function declarations and var (as undefined) are usable before their line of code.', 'Las declaraciones de variables y funciones se mueven al principio de su ámbito durante la compilación, de modo que las funciones declaradas y las var (como undefined) se pueden usar antes de su línea de código.'),
    ('Hoisting', 'Hoisting means all variables are automatically made global.', 'El hoisting significa que todas las variables se vuelven globales automáticamente.'),
    ('Hoisting', 'Hoisting moves code execution to run after the event loop finishes.', 'El hoisting hace que el código se ejecute después de que termine el event loop.'),
    ('The this keyword', 'It depends on how the function is called (call-site): as a method, this is the object; as a plain function call, this is undefined in strict mode or the global object otherwise; arrow functions inherit this lexically.', 'Depende de cómo se llama a la función (call-site): como método, this es el objeto; como llamada a función normal, this es undefined en modo estricto o el objeto global en caso contrario; las funciones flecha heredan this léxicamente.'),
    ('The this keyword', '`this` always refers to the function itself.', '`this` siempre hace referencia a la propia función.'),
    ('The this keyword', '`this` is fixed at the moment the function is defined, regardless of how it''s called.', '`this` queda fijado en el momento en que se define la función, sin importar cómo se llame.'),
    ('call, apply and bind', 'call and apply invoke the function immediately with a given this (call takes args individually, apply takes an array); bind returns a new function with this permanently set.', 'call y apply invocan la función inmediatamente con un this dado (call recibe los argumentos por separado, apply los recibe como array); bind devuelve una nueva función con this fijado de forma permanente.'),
    ('call, apply and bind', 'call and bind invoke immediately, apply returns a new function.', 'call y bind invocan de inmediato, apply devuelve una nueva función.'),
    ('call, apply and bind', 'They are all deprecated in favor of arrow functions.', 'Los tres están obsoletos a favor de las funciones flecha.'),
    ('Debounce vs throttle', 'Debounce delays execution until a pause in calls has occurred; throttle limits execution to at most once per fixed time interval regardless of how often it''s called.', 'Debounce retrasa la ejecución hasta que se produce una pausa en las llamadas; throttle limita la ejecución a como mucho una vez por intervalo de tiempo fijo, sin importar cuántas veces se llame.'),
    ('Debounce vs throttle', 'Throttle waits for a pause in calls; debounce runs at a fixed interval.', 'Throttle espera a que haya una pausa en las llamadas; debounce se ejecuta a intervalos fijos.'),
    ('Debounce vs throttle', 'They are two names for the same rate-limiting technique.', 'Son dos nombres para la misma técnica de limitación de frecuencia.'),
    ('Shallow vs deep copy', 'A shallow copy duplicates only the top-level properties (nested objects are still shared by reference); a deep copy recursively duplicates every nested object too.', 'Una copia superficial duplica solo las propiedades del primer nivel (los objetos anidados se siguen compartiendo por referencia); una copia profunda duplica recursivamente también cada objeto anidado.'),
    ('Shallow vs deep copy', 'A shallow copy is always faster but produces an invalid object.', 'Una copia superficial siempre es más rápida pero produce un objeto inválido.'),
    ('Shallow vs deep copy', 'A deep copy only works on arrays, not plain objects.', 'Una copia profunda solo funciona con arrays, no con objetos normales.'),
    ('WeakMap vs Map', 'WeakMap holds its keys weakly (object keys only), allowing garbage collection when there are no other references, and is not iterable; Map holds strong references and is iterable.', 'WeakMap mantiene sus claves de forma débil (solo objetos como clave), permitiendo que se recolecten cuando no hay otras referencias, y no es iterable; Map mantiene referencias fuertes y sí es iterable.'),
    ('WeakMap vs Map', 'WeakMap is just a slower version of Map with the same guarantees.', 'WeakMap es solo una versión más lenta de Map con las mismas garantías.'),
    ('WeakMap vs Map', 'WeakMap allows primitive keys while Map only allows object keys.', 'WeakMap permite claves primitivas mientras que Map solo permite claves de tipo objeto.'),
    ('Optional chaining and nullish coalescing', '?. (optional chaining) short-circuits to undefined when accessing a property on null/undefined instead of throwing; ?? (nullish coalescing) returns the right-hand value only when the left is null or undefined.', '?. (optional chaining) devuelve undefined en cortocircuito al acceder a una propiedad de null/undefined en lugar de lanzar un error; ?? (nullish coalescing) devuelve el valor de la derecha solo cuando el de la izquierda es null o undefined.'),
    ('Optional chaining and nullish coalescing', '?. throws a custom error and ?? always returns the left-hand value.', '?. lanza un error personalizado y ?? siempre devuelve el valor de la izquierda.'),
    ('Optional chaining and nullish coalescing', 'Both operators are only available in TypeScript, not plain JavaScript.', 'Ambos operadores solo están disponibles en TypeScript, no en JavaScript puro.'),
    ('Handling errors in async/await', 'Wrap the awaited call in a try/catch block, or attach .catch() to the returned promise, since a rejected awaited promise throws inside the async function.', 'Envuelve la llamada con await en un bloque try/catch, o añade .catch() a la promise devuelta, ya que una promise esperada que se rechaza lanza una excepción dentro de la función async.'),
    ('Handling errors in async/await', 'async/await cannot handle errors; you must always fall back to .then/.catch.', 'async/await no puede manejar errores; siempre hay que recurrir a .then/.catch.'),
    ('Handling errors in async/await', 'Errors in async functions are silently ignored unless you check a return code.', 'Los errores en funciones async se ignoran silenciosamente a menos que compruebes un código de retorno.'),
    ('CommonJS vs ES Modules', 'CommonJS loads modules synchronously with require/module.exports (Node''s original system); ES Modules use static import/export syntax, are statically analyzable, and support tree shaking.', 'CommonJS carga los módulos de forma síncrona con require/module.exports (el sistema original de Node); los ES Modules usan la sintaxis estática import/export, son analizables estáticamente y admiten tree shaking.'),
    ('CommonJS vs ES Modules', 'CommonJS is the browser standard and ES Modules only work in Node.js.', 'CommonJS es el estándar del navegador y los ES Modules solo funcionan en Node.js.'),
    ('CommonJS vs ES Modules', 'They are fully interchangeable with no differences in behavior.', 'Son totalmente intercambiables y no tienen diferencias de comportamiento.'),
    ('Currying', 'Currying transforms a function taking multiple arguments into a sequence of functions each taking a single argument, enabling partial application and function composition.', 'El currying transforma una función que recibe varios argumentos en una secuencia de funciones que reciben un único argumento cada una, lo que permite la aplicación parcial y la composición de funciones.'),
    ('Currying', 'Currying is a way to make functions run in parallel.', 'El currying es una forma de hacer que las funciones se ejecuten en paralelo.'),
    ('Currying', 'Currying converts synchronous functions into asynchronous ones.', 'El currying convierte funciones síncronas en asíncronas.'),
    ('keyof vs typeof', 'keyof takes a type and returns the union of its property names; typeof takes a value and returns its type', 'keyof toma un tipo y devuelve la unión de los nombres de sus propiedades; typeof toma un valor y devuelve su tipo'),
    ('keyof vs typeof', 'keyof returns the values of an object at runtime; typeof returns its keys', 'keyof devuelve los valores de un objeto en tiempo de ejecución; typeof devuelve sus claves'),
    ('keyof vs typeof', 'They are aliases: both return the union of property names of a type', 'Son alias: ambos devuelven la unión de los nombres de propiedades de un tipo'),
    ('What are generics?', 'Type parameters that let a function or type work with many types while preserving type safety, e.g. function first<T>(xs: T[]): T', 'Parámetros de tipo que permiten que una función o tipo trabaje con muchos tipos sin perder la seguridad de tipos, p. ej. function first<T>(xs: T[]): T'),
    ('What are generics?', 'A way to disable type checking for a function, similar to using any', 'Una forma de desactivar la comprobación de tipos de una función, similar a usar any'),
    ('What are generics?', 'Built-in utility types such as Partial and Pick only', 'Solo los utility types integrados como Partial y Pick'),
    ('Conditional types', 'Types of the form T extends U ? X : Y that choose a type based on a condition, e.g. NonNullable<T>', 'Tipos de la forma T extends U ? X : Y que eligen un tipo según una condición, p. ej. NonNullable<T>'),
    ('Conditional types', 'Runtime if statements that TypeScript checks at compile time', 'Sentencias if en tiempo de ejecución que TypeScript comprueba en tiempo de compilación'),
    ('Conditional types', 'Types that are only applied when strict mode is disabled', 'Tipos que solo se aplican cuando el modo estricto está desactivado'),
    ('Mapped types', 'Types that transform each property of another type, e.g. type Readonly<T> = { readonly [K in keyof T]: T[K] }', 'Tipos que transforman cada propiedad de otro tipo, p. ej. type Readonly<T> = { readonly [K in keyof T]: T[K] }'),
    ('Mapped types', 'The Map<K, V> class from JavaScript', 'La clase Map<K, V> de JavaScript'),
    ('Mapped types', 'Types generated from a JSON file at build time', 'Tipos generados a partir de un archivo JSON en tiempo de build'),
    ('infer keyword', 'Used inside a conditional type to capture a type into a variable, e.g. T extends (...a: any[]) => infer R ? R : never', 'Se usa dentro de un tipo condicional para capturar un tipo en una variable, p. ej. T extends (...a: any[]) => infer R ? R : never'),
    ('infer keyword', 'It tells TypeScript to infer types for the whole project automatically', 'Le indica a TypeScript que infiera los tipos de todo el proyecto automáticamente'),
    ('infer keyword', 'It converts a runtime value into a type', 'Convierte un valor en tiempo de ejecución en un tipo'),
    ('Structural typing vs nominal typing', 'TypeScript is structural: types are compatible if their shapes match, regardless of their names', 'TypeScript es estructural: los tipos son compatibles si sus formas coinciden, sin importar sus nombres'),
    ('Structural typing vs nominal typing', 'TypeScript is nominal: two types are compatible only if they have the same name', 'TypeScript es nominal: dos tipos son compatibles solo si tienen el mismo nombre'),
    ('Structural typing vs nominal typing', 'TypeScript uses nominal typing for interfaces and structural typing only for classes', 'TypeScript usa tipado nominal para las interfaces y tipado estructural solo para las clases'),
    ('any vs unknown', 'any disables type checking entirely; unknown also accepts any value but requires a type check or assertion before you can use it, preserving type safety.', 'any desactiva por completo la comprobación de tipos; unknown también acepta cualquier valor pero exige una comprobación o aserción de tipo antes de poder usarlo, preservando la seguridad de tipos.'),
    ('any vs unknown', 'any and unknown are interchangeable aliases.', 'any y unknown son alias intercambiables.'),
    ('any vs unknown', 'unknown can only be used for function return types.', 'unknown solo se puede usar para tipos de retorno de funciones.'),
    ('Enums', 'Enums define a named set of related constant values (e.g. Direction.Up), improving readability over raw string/number literals scattered through the code.', 'Los enums definen un conjunto con nombre de valores constantes relacionados (p. ej. Direction.Up), mejorando la legibilidad frente a literales de string/número sueltos por el código.'),
    ('Enums', 'Enums are TypeScript''s only way to define arrays with fixed length.', 'Los enums son la única forma que tiene TypeScript de definir arrays de longitud fija.'),
    ('Enums', 'Enums are compiled away and unusable at runtime.', 'Los enums desaparecen al compilar y no se pueden usar en tiempo de ejecución.'),
    ('type vs interface', 'Both can describe object shapes; interfaces support declaration merging and are typically preferred for public object APIs, while type aliases can also represent unions, tuples, and primitives that interfaces cannot.', 'Ambos pueden describir la forma de un objeto; las interfaces admiten declaration merging y suelen preferirse para APIs públicas de objetos, mientras que los alias de tipo también pueden representar uniones, tuplas y primitivos que las interfaces no pueden.'),
    ('type vs interface', 'type can only describe primitives, interface only describes objects.', 'type solo puede describir primitivos, interface solo describe objetos.'),
    ('type vs interface', 'They are fully identical in every capability with no differences.', 'Son totalmente idénticos en todas sus capacidades, sin diferencias.'),
    ('Union vs intersection types', 'A union type allows a value to be one of several types (A | B); an intersection type combines multiple types into one that must satisfy all of them (A & B).', 'Un tipo unión permite que un valor sea uno de varios tipos (A | B); un tipo intersección combina varios tipos en uno que debe satisfacerlos todos (A & B).'),
    ('Union vs intersection types', 'Union requires all types to be satisfied; intersection allows any one of them.', 'La unión exige que se cumplan todos los tipos; la intersección permite cualquiera de ellos.'),
    ('Union vs intersection types', 'Union and intersection only apply to primitive types, not objects.', 'Unión e intersección solo se aplican a tipos primitivos, no a objetos.'),
    ('Type guards', 'A runtime check (like typeof, instanceof, or a custom predicate function returning `x is Type`) that narrows a variable''s type within a conditional block.', 'Una comprobación en tiempo de ejecución (como typeof, instanceof o una función predicado personalizada que devuelve `x is Type`) que acota el tipo de una variable dentro de un bloque condicional.'),
    ('Type guards', 'A compiler flag that disables type checking for a file.', 'Una opción del compilador que desactiva la comprobación de tipos de un archivo.'),
    ('Type guards', 'A decorator that guards a class from being extended.', 'Un decorador que impide que una clase pueda extenderse.'),
    ('Pick and Omit', 'Pick<T, K> creates a type with only the listed keys from T; Omit<T, K> creates a type with all keys of T except the listed ones.', 'Pick<T, K> crea un tipo solo con las claves indicadas de T; Omit<T, K> crea un tipo con todas las claves de T excepto las indicadas.'),
    ('Pick and Omit', 'Pick selects values at runtime; Omit deletes properties from the original object.', 'Pick selecciona valores en tiempo de ejecución; Omit elimina propiedades del objeto original.'),
    ('Pick and Omit', 'Both utility types only work on arrays, not object types.', 'Ambos utility types solo funcionan con arrays, no con tipos objeto.'),
    ('Discriminated unions', 'A union of object types that share a common literal ''tag'' property (e.g. kind: ''circle'' | ''square''), letting TypeScript narrow the exact shape based on that tag in a switch or if.', 'Una unión de tipos objeto que comparten una propiedad literal común a modo de ''etiqueta'' (p. ej. kind: ''circle'' | ''square''), que permite a TypeScript acotar la forma exacta según esa etiqueta en un switch o if.'),
    ('Discriminated unions', 'A union type that TypeScript refuses to compile because it''s ambiguous.', 'Un tipo unión que TypeScript se niega a compilar por ser ambiguo.'),
    ('Discriminated unions', 'An enum where every member must have a unique numeric value.', 'Un enum en el que cada miembro debe tener un valor numérico único.'),
    ('Declaration merging', 'TypeScript''s ability to combine multiple declarations with the same name (e.g. two `interface Foo` blocks) into a single merged definition, commonly used to extend third-party types.', 'La capacidad de TypeScript de combinar varias declaraciones con el mismo nombre (p. ej. dos bloques `interface Foo`) en una única definición fusionada, usada habitualmente para ampliar tipos de terceros.'),
    ('Declaration merging', 'A build step that merges every .ts file in the project into one bundle.', 'Un paso del build que fusiona todos los archivos .ts del proyecto en un único bundle.'),
    ('Declaration merging', 'A runtime feature that merges two objects deeply.', 'Una funcionalidad en tiempo de ejecución que fusiona dos objetos en profundidad.'),
    ('Non-null assertion operator', 'It tells the compiler to treat a value as non-null/non-undefined, suppressing the type error without any runtime check — it''s purely a compile-time assertion.', 'Le indica al compilador que trate un valor como no nulo/no undefined, suprimiendo el error de tipo sin ninguna comprobación en tiempo de ejecución: es una aserción puramente de compilación.'),
    ('Non-null assertion operator', 'It throws a runtime error if the value is null or undefined.', 'Lanza un error en tiempo de ejecución si el valor es null o undefined.'),
    ('Non-null assertion operator', 'It converts the value to a boolean, negating it.', 'Convierte el valor a booleano, negándolo.'),
    ('The satisfies operator', 'It checks that an expression matches a given type without widening or changing the expression''s inferred type, unlike a type annotation which would widen it.', 'Comprueba que una expresión cumple un tipo dado sin ampliar ni cambiar el tipo inferido de la expresión, a diferencia de una anotación de tipo que sí lo ampliaría.'),
    ('The satisfies operator', 'It replaces `as` for all type assertions and behaves identically.', 'Sustituye a `as` para todas las aserciones de tipo y se comporta igual.'),
    ('The satisfies operator', 'It runs a runtime validation against a JSON schema.', 'Ejecuta una validación en tiempo de ejecución contra un JSON schema.'),
    ('Template literal types', 'Types built using template string syntax (e.g. type Event = `on${Capitalize<string>}`) that combine string literal types to generate new, precise string types.', 'Tipos construidos con la sintaxis de plantillas de cadena (p. ej. type Event = `on${Capitalize<string>}`) que combinan tipos literales de cadena para generar nuevos tipos de cadena precisos.'),
    ('Template literal types', 'A way to embed TypeScript code inside template literal strings at runtime.', 'Una forma de incrustar código TypeScript dentro de plantillas de cadena en tiempo de ejecución.'),
    ('Template literal types', 'A syntax for writing multi-line comments in type declarations.', 'Una sintaxis para escribir comentarios multilínea en las declaraciones de tipo.'),
    ('Function overloads', 'Multiple type signatures declared for the same function name, letting callers see different valid parameter/return combinations while a single implementation handles them all.', 'Varias firmas de tipo declaradas para el mismo nombre de función, que permiten a quien la llama ver distintas combinaciones válidas de parámetros/retorno, mientras una única implementación las gestiona todas.'),
    ('Function overloads', 'Overloads let you define multiple functions with the same name and different runtime behavior automatically dispatched.', 'Las sobrecargas permiten definir varias funciones con el mismo nombre y comportamiento en tiempo de ejecución distinto, despachadas automáticamente.'),
    ('Function overloads', 'Overloads are only allowed on class constructors, not standalone functions.', 'Las sobrecargas solo están permitidas en constructores de clase, no en funciones sueltas.'),
    ('Ambient declarations (.d.ts)', 'It describes the shape of existing JavaScript code (types, functions, modules) without providing implementations, so TypeScript can type-check code that uses plain JS or third-party libraries.', 'Describe la forma de código JavaScript ya existente (tipos, funciones, módulos) sin aportar implementaciones, de modo que TypeScript pueda comprobar tipos en código que usa JS puro o librerías de terceros.'),
    ('Ambient declarations (.d.ts)', '.d.ts files contain the compiled JavaScript output of a TypeScript project.', 'Los archivos .d.ts contienen el JavaScript compilado de salida de un proyecto TypeScript.'),
    ('Ambient declarations (.d.ts)', 'They are required to run TypeScript code in Node.js.', 'Son necesarios para ejecutar código TypeScript en Node.js.'),
    ('strictNullChecks', 'It makes null and undefined distinct types that must be explicitly included in a type''s definition, preventing accidental null/undefined access errors that are otherwise silently allowed.', 'Convierte null y undefined en tipos distintos que deben incluirse explícitamente en la definición de un tipo, evitando errores accidentales de acceso a null/undefined que de otro modo se permitirían en silencio.'),
    ('strictNullChecks', 'It removes all null and undefined values from objects at compile time.', 'Elimina todos los valores null y undefined de los objetos en tiempo de compilación.'),
    ('strictNullChecks', 'It disables the use of the null keyword anywhere in the codebase.', 'Desactiva el uso de la palabra clave null en cualquier parte del código.'),
    ('What is useMemo?', 'A hook that memoizes the result of a computation and only recomputes it when its dependencies change', 'Un hook que memoriza el resultado de un cálculo y solo lo vuelve a calcular cuando cambian sus dependencias'),
    ('What is useMemo?', 'A hook that memoizes a whole component to skip re-renders', 'Un hook que memoriza un componente entero para evitar re-renders'),
    ('What is useMemo?', 'A hook that persists state to localStorage', 'Un hook que persiste el estado en localStorage'),
    ('useCallback vs useMemo', 'useCallback memoizes a function reference; useMemo memoizes the value a function returns', 'useCallback memoriza la referencia de una función; useMemo memoriza el valor que devuelve una función'),
    ('useCallback vs useMemo', 'useCallback runs after render, useMemo runs before render', 'useCallback se ejecuta después del render, useMemo se ejecuta antes del render'),
    ('useCallback vs useMemo', 'useMemo is for class components, useCallback for function components', 'useMemo es para componentes de clase, useCallback para componentes función'),
    ('Explain React.memo', 'A higher-order component that skips re-rendering when its props are shallowly equal to the previous props', 'Un higher-order component que evita volver a renderizar cuando sus props son superficialmente iguales a las anteriores'),
    ('Explain React.memo', 'A hook that caches the result of an expensive calculation', 'Un hook que cachea el resultado de un cálculo costoso'),
    ('Explain React.memo', 'A function that deep-compares state to avoid all re-renders of the app', 'Una función que compara el estado en profundidad para evitar todos los re-renders de la app'),
    ('useReducer vs useState', 'useReducer is better for complex state with many related transitions, centralizing logic in a pure reducer', 'useReducer es mejor para estado complejo con muchas transiciones relacionadas, centralizando la lógica en un reducer puro'),
    ('useReducer vs useState', 'useReducer is always faster than useState', 'useReducer siempre es más rápido que useState'),
    ('useReducer vs useState', 'useState cannot store objects, so useReducer is required for them', 'useState no puede almacenar objetos, por lo que se necesita useReducer para ellos'),
    ('Render props vs custom hooks', 'Custom hooks are preferred today: they share logic without extra nesting in the component tree', 'Hoy se prefieren los hooks personalizados: comparten lógica sin añadir anidamiento extra en el árbol de componentes'),
    ('Render props vs custom hooks', 'Render props are required to share state between components', 'Los render props son obligatorios para compartir estado entre componentes'),
    ('Render props vs custom hooks', 'Custom hooks only work in class components', 'Los hooks personalizados solo funcionan en componentes de clase'),
    ('Concurrent React and useTransition', 'useTransition marks updates as non-urgent so React can keep the UI responsive, and React 18 batches updates automatically', 'useTransition marca actualizaciones como no urgentes para que React mantenga la UI responsiva, y React 18 agrupa (batching) las actualizaciones automáticamente'),
    ('Concurrent React and useTransition', 'useTransition adds CSS transitions to components', 'useTransition añade transiciones CSS a los componentes'),
    ('Concurrent React and useTransition', 'Concurrent React runs components on multiple threads', 'Concurrent React ejecuta los componentes en varios hilos'),
    ('Virtual DOM reconciliation', 'React diffs the new tree against the previous one and uses keys to match list items, applying minimal DOM changes', 'React compara el nuevo árbol con el anterior y usa las keys para emparejar los elementos de una lista, aplicando el mínimo cambio posible al DOM'),
    ('Virtual DOM reconciliation', 'React re-creates the entire real DOM on every render', 'React recrea todo el DOM real en cada render'),
    ('Virtual DOM reconciliation', 'Keys are only used for styling list items', 'Las keys solo se usan para dar estilo a los elementos de una lista'),
    ('Error boundaries', 'Class components with getDerivedStateFromError/componentDidCatch that catch render errors in their children and show a fallback', 'Componentes de clase con getDerivedStateFromError/componentDidCatch que capturan errores de render en sus hijos y muestran una interfaz alternativa'),
    ('Error boundaries', 'A hook that catches errors in event handlers and async code', 'Un hook que captura errores en manejadores de eventos y código asíncrono'),
    ('Error boundaries', 'A try/catch block placed around ReactDOM.render', 'Un bloque try/catch colocado alrededor de ReactDOM.render'),
    ('Server Components vs Client Components', 'Server Components render on the server and ship no JS to the client; Client Components (use client) can use state, effects and events', 'Los Server Components se renderizan en el servidor y no envían JS al cliente; los Client Components (use client) pueden usar estado, efectos y eventos'),
    ('Server Components vs Client Components', 'Server Components can use useState and useEffect freely', 'Los Server Components pueden usar useState y useEffect libremente'),
    ('Server Components vs Client Components', 'Client Components are rendered only on the server', 'Los Client Components solo se renderizan en el servidor'),
    ('Controlled vs uncontrolled components', 'A controlled component''s value is driven by React state (via value + onChange); an uncontrolled component keeps its own internal DOM state, accessed via a ref when needed.', 'El valor de un componente controlado viene dado por el estado de React (mediante value + onChange); uno no controlado mantiene su propio estado interno en el DOM, accesible mediante una ref cuando hace falta.'),
    ('Controlled vs uncontrolled components', 'Controlled components can only be used with class components.', 'Los componentes controlados solo se pueden usar con componentes de clase.'),
    ('Controlled vs uncontrolled components', 'Uncontrolled components cannot have a default value.', 'Los componentes no controlados no pueden tener un valor por defecto.'),
    ('Lifting state up', 'Moving shared state to the closest common ancestor of the components that need it, then passing it down via props, so multiple components stay in sync.', 'Mover el estado compartido al ancestro común más cercano de los componentes que lo necesitan, y luego pasarlo hacia abajo mediante props, para que varios componentes se mantengan sincronizados.'),
    ('Lifting state up', 'Moving all component state into a global Redux store.', 'Mover todo el estado de los componentes a un store global de Redux.'),
    ('Lifting state up', 'Converting a function component into a class component.', 'Convertir un componente función en un componente de clase.'),
    ('Context API', 'It lets you share data (like theme or auth state) across a component tree without manually passing props down through every intermediate level (prop drilling).', 'Permite compartir datos (como el tema o el estado de autenticación) por todo un árbol de componentes sin pasar props manualmente por cada nivel intermedio (prop drilling).'),
    ('Context API', 'It replaces useState entirely for all local component state.', 'Sustituye por completo a useState para todo el estado local de un componente.'),
    ('Context API', 'It is used only for fetching data from a REST API.', 'Solo se usa para obtener datos de una API REST.'),
    ('useEffect cleanup function', 'It runs before the effect re-runs and when the component unmounts, letting you cancel subscriptions, timers, or event listeners set up by the effect to avoid leaks.', 'Se ejecuta antes de que el efecto se vuelva a ejecutar y cuando el componente se desmonta, permitiendo cancelar suscripciones, temporizadores o listeners de eventos creados por el efecto para evitar fugas.'),
    ('useEffect cleanup function', 'It clears all component state back to its initial values.', 'Restablece todo el estado del componente a sus valores iniciales.'),
    ('useEffect cleanup function', 'It deletes the component from the DOM immediately.', 'Elimina el componente del DOM de inmediato.'),
    ('useRef use cases', 'Accessing a DOM node directly (e.g. focusing an input), and storing a mutable value that persists across renders without triggering a re-render when it changes.', 'Acceder directamente a un nodo del DOM (p. ej. para enfocar un input), y guardar un valor mutable que persiste entre renders sin provocar un nuevo render al cambiar.'),
    ('useRef use cases', 'useRef is only for storing state that should trigger re-renders, like useState.', 'useRef solo sirve para guardar estado que debería provocar re-renders, como useState.'),
    ('useRef use cases', 'useRef can only be used inside class components.', 'useRef solo se puede usar dentro de componentes de clase.'),
    ('Portals', 'ReactDOM.createPortal renders a child into a DOM node outside its parent''s DOM hierarchy while keeping it in the same React component tree — useful for modals, tooltips, and dropdowns that must escape overflow/z-index constraints.', 'ReactDOM.createPortal renderiza un hijo en un nodo del DOM fuera de la jerarquía del DOM de su padre, manteniéndolo en el mismo árbol de componentes de React; útil para modales, tooltips y desplegables que deben escapar de restricciones de overflow/z-index.'),
    ('Portals', 'A Portal is a special hook for fetching data across routes.', 'Un Portal es un hook especial para obtener datos entre rutas.'),
    ('Portals', 'A Portal lets one React app render components from a completely different app.', 'Un Portal permite que una app de React renderice componentes de otra app completamente distinta.'),
    ('Suspense', 'It lets a component ''wait'' for something (like a lazy-loaded chunk or, with supporting data libraries, a data fetch) before rendering, showing a fallback UI in the meantime.', 'Permite que un componente ''espere'' a algo (como un chunk cargado de forma diferida o, con librerías de datos compatibles, una petición de datos) antes de renderizar, mostrando mientras tanto una interfaz alternativa.'),
    ('Suspense', 'Suspense pauses the entire JavaScript engine until data arrives.', 'Suspense pausa todo el motor de JavaScript hasta que llegan los datos.'),
    ('Suspense', 'Suspense is a testing utility for mocking API calls.', 'Suspense es una utilidad de testing para simular llamadas a una API.'),
    ('Rules of hooks', 'Hooks must be called at the top level (never inside loops/conditions/nested functions) and only from React functions, because React relies on the consistent call order across renders to associate state with the right hook.', 'Los hooks deben llamarse en el nivel superior (nunca dentro de bucles/condicionales/funciones anidadas) y solo desde funciones de React, porque React depende de que el orden de llamada sea consistente entre renders para asociar el estado con el hook correcto.'),
    ('Rules of hooks', 'Hooks can be called conditionally as long as the condition never changes.', 'Los hooks se pueden llamar de forma condicional siempre que la condición nunca cambie.'),
    ('Rules of hooks', 'The rules of hooks only apply to useState, not other hooks.', 'Las reglas de los hooks solo se aplican a useState, no a los demás hooks.'),
    ('Why keys matter in lists', 'Keys let React''s reconciliation algorithm identify which items changed, were added, or were removed between renders, instead of re-rendering the whole list or misapplying state to the wrong item.', 'Las keys permiten que el algoritmo de reconciliación de React identifique qué elementos cambiaron, se añadieron o se eliminaron entre renders, en lugar de volver a renderizar toda la lista o aplicar mal el estado a un elemento equivocado.'),
    ('Why keys matter in lists', 'Keys are only used for styling list items with CSS.', 'Las keys solo se usan para dar estilo con CSS a los elementos de una lista.'),
    ('Why keys matter in lists', 'Keys are optional and have no effect on rendering performance or correctness.', 'Las keys son opcionales y no afectan al rendimiento ni a la corrección del renderizado.'),
    ('Prop drilling', 'Passing props through many intermediate components that don''t need them just to reach a deeply nested child, which makes components harder to refactor and reuse.', 'Pasar props a través de muchos componentes intermedios que no las necesitan, solo para llegar a un hijo profundamente anidado, lo que dificulta refactorizar y reutilizar los componentes.'),
    ('Prop drilling', 'A performance optimization technique used to avoid unnecessary re-renders.', 'Una técnica de optimización de rendimiento usada para evitar re-renders innecesarios.'),
    ('Prop drilling', 'A pattern for validating props with PropTypes at every level.', 'Un patrón para validar props con PropTypes en cada nivel.'),
    ('StrictMode double effects', 'To help surface side effects that aren''t properly cleaned up, by intentionally re-running them once to check they behave correctly when mounted, unmounted, and remounted — it only happens in development, not production.', 'Para ayudar a detectar efectos secundarios que no se limpian correctamente, volviéndolos a ejecutar a propósito una vez para comprobar que se comportan bien al montar, desmontar y volver a montar; solo ocurre en desarrollo, no en producción.'),
    ('StrictMode double effects', 'It''s a bug in React that will be fixed in a future release.', 'Es un fallo de React que se corregirá en una futura versión.'),
    ('StrictMode double effects', 'It doubles rendering performance by running effects in parallel.', 'Duplica el rendimiento del renderizado ejecutando los efectos en paralelo.'),
    ('What is libuv?', 'The C library that implements the Node.js event loop, async I/O and the thread pool', 'La librería en C que implementa el event loop de Node.js, la I/O asíncrona y el thread pool'),
    ('What is libuv?', 'The JavaScript engine that compiles JS to machine code in Node.js', 'El motor de JavaScript que compila JS a código máquina en Node.js'),
    ('What is libuv?', 'A package manager alternative to npm', 'Una alternativa a npm como gestor de paquetes'),
    ('Streams in Node.js', 'Abstractions to process data piece by piece (readable, writable, duplex, transform) without loading it all in memory, with backpressure', 'Abstracciones para procesar datos poco a poco (readable, writable, duplex, transform) sin cargarlos todos en memoria, con backpressure'),
    ('Streams in Node.js', 'A way to run JavaScript on multiple CPU cores', 'Una forma de ejecutar JavaScript en varios núcleos de CPU'),
    ('Streams in Node.js', 'Arrays that are automatically persisted to disk', 'Arrays que se persisten automáticamente en disco'),
    ('Cluster mode vs worker threads', 'cluster forks processes that share a port to scale HTTP servers; worker_threads run CPU-heavy work in threads within one process', 'cluster bifurca procesos que comparten un puerto para escalar servidores HTTP; worker_threads ejecuta trabajo intensivo de CPU en hilos dentro de un mismo proceso'),
    ('Cluster mode vs worker threads', 'They are identical APIs with different names', 'Son APIs idénticas con nombres distintos'),
    ('Cluster mode vs worker threads', 'worker_threads are used to share a server port between processes', 'worker_threads se usa para compartir el puerto de un servidor entre procesos'),
    ('Memory management and V8 garbage collection', 'V8 uses a generational GC: fast scavenges for the young generation and mark-sweep-compact for the old one; profile with heap snapshots', 'V8 usa un GC generacional: scavenges rápidos para la generación joven y mark-sweep-compact para la vieja; se hace profiling con heap snapshots'),
    ('Memory management and V8 garbage collection', 'Node.js uses manual memory management with malloc and free', 'Node.js usa gestión manual de memoria con malloc y free'),
    ('Memory management and V8 garbage collection', 'V8 uses only reference counting, so it cannot collect cycles', 'V8 solo usa conteo de referencias, por lo que no puede recolectar ciclos'),
    ('Middleware pipeline pattern', 'Each middleware receives req, res and next, and calls next() to pass control to the next one in the chain', 'Cada middleware recibe req, res y next, y llama a next() para pasar el control al siguiente de la cadena'),
    ('Middleware pipeline pattern', 'All middleware functions run in parallel for every request', 'Todas las funciones middleware se ejecutan en paralelo para cada petición'),
    ('Middleware pipeline pattern', 'Middleware can only run after the response has been sent', 'El middleware solo puede ejecutarse después de haber enviado la respuesta'),
    ('Graceful shutdown in Node.js', 'On SIGTERM stop accepting connections, let in-flight requests finish, close DB pools, then exit', 'Al recibir SIGTERM, dejar de aceptar conexiones nuevas, permitir que terminen las peticiones en curso, cerrar los pools de la base de datos y luego salir'),
    ('Graceful shutdown in Node.js', 'Call process.exit(0) immediately when SIGTERM is received', 'Llamar a process.exit(0) inmediatamente al recibir SIGTERM'),
    ('Graceful shutdown in Node.js', 'Ignore SIGTERM so the server never stops', 'Ignorar SIGTERM para que el servidor nunca se detenga'),
    ('Process.nextTick vs setImmediate', 'nextTick runs before any other queued work in the current phase; setImmediate runs in the check phase after I/O', 'nextTick se ejecuta antes que cualquier otro trabajo encolado en la fase actual; setImmediate se ejecuta en la fase check, después de la I/O'),
    ('Process.nextTick vs setImmediate', 'setImmediate always runs before process.nextTick', 'setImmediate siempre se ejecuta antes que process.nextTick'),
    ('Process.nextTick vs setImmediate', 'Both are just aliases of setTimeout(fn, 0)', 'Ambos son solo alias de setTimeout(fn, 0)'),
    ('require vs import', 'require is CommonJS, resolved synchronously at runtime; import is the ES Modules syntax, statically analyzed and resolved before execution, enabling tree shaking and top-level await.', 'require es CommonJS y se resuelve de forma síncrona en tiempo de ejecución; import es la sintaxis de ES Modules, se analiza estáticamente y se resuelve antes de la ejecución, lo que permite tree shaking y top-level await.'),
    ('require vs import', 'They are identical keywords that Node treats the same way internally.', 'Son palabras clave idénticas que Node trata igual internamente.'),
    ('require vs import', 'require only works in the browser, import only works in Node.js.', 'require solo funciona en el navegador, import solo funciona en Node.js.'),
    ('CommonJS module caching', 'No — Node caches the exported module object by resolved file path after the first require(), so subsequent requires return the same cached instance instead of re-running the module code.', 'No: Node cachea el objeto exportado del módulo según la ruta de archivo resuelta tras el primer require(), así que los siguientes require devuelven la misma instancia en caché en lugar de volver a ejecutar el código del módulo.'),
    ('CommonJS module caching', 'Yes, every call to require() re-executes the entire module from scratch.', 'Sí, cada llamada a require() vuelve a ejecutar el módulo entero desde cero.'),
    ('CommonJS module caching', 'Only modules inside node_modules are cached; local files are always re-executed.', 'Solo se cachean los módulos dentro de node_modules; los archivos locales siempre se vuelven a ejecutar.'),
    ('Environment variables and dotenv', 'Values are read from process.env, often loaded from a local .env file via a package like dotenv during development, while production sets real environment variables through the hosting platform.', 'Los valores se leen de process.env, a menudo cargados desde un archivo .env local mediante un paquete como dotenv durante el desarrollo, mientras que en producción las variables de entorno reales las define la plataforma de hosting.'),
    ('Environment variables and dotenv', 'Environment variables must be hardcoded directly into the source code.', 'Las variables de entorno deben escribirse directamente en el código fuente.'),
    ('Environment variables and dotenv', 'Node.js has no concept of environment variables; only command-line arguments work.', 'Node.js no tiene el concepto de variables de entorno; solo funcionan los argumentos de línea de comandos.'),
    ('Error-first callbacks', 'A callback''s first parameter is reserved for an error (or null if none occurred), and subsequent parameters carry the result — the standard pattern before Promises became common.', 'El primer parámetro de un callback se reserva para un error (o null si no hubo ninguno), y los siguientes parámetros llevan el resultado; el patrón estándar antes de que las Promises se popularizaran.'),
    ('Error-first callbacks', 'It means the callback function must be defined before any other code in the file.', 'Significa que la función callback debe definirse antes que cualquier otro código del archivo.'),
    ('Error-first callbacks', 'It''s a convention where errors are thrown instead of passed as arguments.', 'Es una convención en la que los errores se lanzan en lugar de pasarse como argumentos.'),
    ('child_process module', 'It lets Node spawn and communicate with OS-level subprocesses (via spawn, exec, fork, execFile) — useful for running shell commands or CPU-heavy scripts outside the main event loop.', 'Permite a Node lanzar y comunicarse con subprocesos del sistema operativo (mediante spawn, exec, fork, execFile), útil para ejecutar comandos de shell o scripts intensivos de CPU fuera del event loop principal.'),
    ('child_process module', 'It creates additional V8 isolates that share the same memory as the parent.', 'Crea isolates de V8 adicionales que comparten la misma memoria que el proceso padre.'),
    ('child_process module', 'It''s used exclusively for spawning new HTTP servers.', 'Se usa exclusivamente para lanzar nuevos servidores HTTP.'),
    ('Buffer class', 'It represents a fixed-length chunk of raw binary data in memory, used for handling things like file I/O, network protocols, and streams before Node.js supported TypedArrays natively.', 'Representa un bloque de longitud fija de datos binarios en memoria, usado para cosas como I/O de archivos, protocolos de red y streams, desde antes de que Node.js soportara TypedArrays de forma nativa.'),
    ('Buffer class', 'Buffer is a queue data structure used to throttle incoming HTTP requests.', 'Buffer es una estructura de datos tipo cola usada para limitar la frecuencia de las peticiones HTTP entrantes.'),
    ('Buffer class', 'Buffer stores only UTF-8 text and cannot hold binary data.', 'Buffer solo almacena texto UTF-8 y no puede contener datos binarios.'),
    ('fs sync vs async', 'readFileSync blocks the event loop until the file is fully read; readFile is asynchronous and uses a callback (or Promise via fs/promises), letting other work proceed while I/O happens.', 'readFileSync bloquea el event loop hasta que el archivo se lee por completo; readFile es asíncrono y usa un callback (o Promise vía fs/promises), permitiendo que otro trabajo avance mientras ocurre la I/O.'),
    ('fs sync vs async', 'readFileSync is faster in every scenario because it skips the event loop.', 'readFileSync es más rápido en todos los casos porque se salta el event loop.'),
    ('fs sync vs async', 'readFile can only read files smaller than 1MB.', 'readFile solo puede leer archivos de menos de 1MB.'),
    ('Express error-handling middleware', 'Define a middleware function with four parameters (err, req, res, next) placed after your routes; Express recognizes the arity and routes errors passed to next(err) there.', 'Definiendo una función middleware con cuatro parámetros (err, req, res, next) colocada después de tus rutas; Express reconoce esa cantidad de parámetros y envía ahí los errores pasados a next(err).'),
    ('Express error-handling middleware', 'Wrap the entire app.listen() call in a single global try/catch block.', 'Envolviendo toda la llamada a app.listen() en un único bloque try/catch global.'),
    ('Express error-handling middleware', 'Error handling in Express requires a separate error-handling server.', 'El manejo de errores en Express requiere un servidor de errores independiente.'),
    ('Rate limiting middleware', 'Track request counts per client (e.g. by IP or API key) within a time window, using middleware (like express-rate-limit or a Redis-backed counter) that rejects requests once the limit is exceeded.', 'Llevando la cuenta de peticiones por cliente (p. ej. por IP o API key) dentro de una ventana de tiempo, mediante un middleware (como express-rate-limit o un contador respaldado por Redis) que rechaza las peticiones al superar el límite.'),
    ('Rate limiting middleware', 'Rate limiting must be implemented at the database level, never in application code.', 'El rate limiting debe implementarse a nivel de base de datos, nunca en el código de la aplicación.'),
    ('Rate limiting middleware', 'Node.js automatically rate-limits all incoming HTTP requests by default.', 'Node.js limita automáticamente todas las peticiones HTTP entrantes por defecto.'),
    ('npm vs npx', 'npm installs and manages packages; npx executes a package''s binary directly (installing it temporarily if not already present) without adding it as a project dependency.', 'npm instala y gestiona paquetes; npx ejecuta directamente el binario de un paquete (instalándolo temporalmente si no está ya presente) sin añadirlo como dependencia del proyecto.'),
    ('npm vs npx', 'npx is only used to publish packages, never to run them.', 'npx solo se usa para publicar paquetes, nunca para ejecutarlos.'),
    ('npm vs npx', 'npm and npx are two names for the exact same command.', 'npm y npx son dos nombres para exactamente el mismo comando.'),
    ('package-lock.json purpose', 'It records the exact resolved version of every installed dependency (and sub-dependency), ensuring everyone who installs the project gets identical dependency trees.', 'Registra la versión exacta resuelta de cada dependencia instalada (y subdependencia), garantizando que todo el que instale el proyecto obtenga árboles de dependencias idénticos.'),
    ('package-lock.json purpose', 'It stores the compiled JavaScript output of the project.', 'Almacena el JavaScript compilado de salida del proyecto.'),
    ('package-lock.json purpose', 'It lists which packages are explicitly forbidden from being installed.', 'Lista qué paquetes están explícitamente prohibidos de instalar.'),
    ('Health check endpoints', 'So load balancers, orchestrators (like Kubernetes), and monitoring tools can automatically verify the service is running and ready to accept traffic.', 'Para que los balanceadores de carga, orquestadores (como Kubernetes) y herramientas de monitorización puedan verificar automáticamente que el servicio está en marcha y listo para recibir tráfico.'),
    ('Health check endpoints', 'It''s required by the HTTP specification for every server.', 'Lo exige la especificación HTTP para todo servidor.'),
    ('Health check endpoints', 'It''s used only to display the server''s uptime to end users in the UI.', 'Solo se usa para mostrar el uptime del servidor a los usuarios finales en la interfaz.'),
    ('Debugging with --inspect', 'Start Node with the --inspect (or --inspect-brk to pause on the first line) flag, which opens a debugging port that Chrome DevTools (via chrome://inspect) or an IDE can attach to.', 'Arrancando Node con el flag --inspect (o --inspect-brk para pausar en la primera línea), que abre un puerto de depuración al que Chrome DevTools (vía chrome://inspect) o un IDE pueden conectarse.'),
    ('Debugging with --inspect', 'Node.js processes can only be debugged using console.log statements.', 'Los procesos Node.js solo se pueden depurar usando sentencias console.log.'),
    ('Debugging with --inspect', 'You must recompile Node.js from source with debug symbols enabled.', 'Hay que recompilar Node.js desde el código fuente con los símbolos de depuración activados.'),
    ('INNER JOIN vs LEFT JOIN', 'INNER JOIN returns only matching rows; LEFT JOIN returns all left rows and NULLs where the right side has no match', 'INNER JOIN devuelve solo las filas coincidentes; LEFT JOIN devuelve todas las filas de la izquierda y NULL donde la derecha no tiene coincidencia'),
    ('INNER JOIN vs LEFT JOIN', 'INNER JOIN returns all rows from both tables; LEFT JOIN returns only matching rows', 'INNER JOIN devuelve todas las filas de ambas tablas; LEFT JOIN devuelve solo las coincidentes'),
    ('INNER JOIN vs LEFT JOIN', 'LEFT JOIN is just a faster version of INNER JOIN', 'LEFT JOIN es solo una versión más rápida de INNER JOIN'),
    ('WHERE vs HAVING', 'WHERE filters rows before GROUP BY; HAVING filters groups after GROUP BY and can use aggregates', 'WHERE filtra filas antes del GROUP BY; HAVING filtra grupos después del GROUP BY y puede usar funciones de agregación'),
    ('WHERE vs HAVING', 'HAVING filters rows before grouping; WHERE filters after grouping', 'HAVING filtra filas antes de agrupar; WHERE filtra después de agrupar'),
    ('WHERE vs HAVING', 'They are interchangeable in every query', 'Son intercambiables en cualquier consulta'),
    ('What is a database index?', 'A data structure (usually a B-tree) that speeds up lookups on columns at the cost of extra storage and slower writes', 'Una estructura de datos (normalmente un B-tree) que acelera las búsquedas en columnas a costa de más almacenamiento y escrituras más lentas'),
    ('What is a database index?', 'The primary key column, which every table must have', 'La columna de clave primaria, que toda tabla debe tener'),
    ('What is a database index?', 'A cache that stores the full results of every query', 'Una caché que almacena el resultado completo de cada consulta'),
    ('EXPLAIN and query optimization', 'EXPLAIN ANALYZE shows the real execution plan and timings; look for sequential scans, bad row estimates and missing indexes', 'EXPLAIN ANALYZE muestra el plan de ejecución real y los tiempos; hay que fijarse en sequential scans, estimaciones de filas erróneas e índices que faltan'),
    ('EXPLAIN and query optimization', 'EXPLAIN rewrites the query automatically to make it faster', 'EXPLAIN reescribe la consulta automáticamente para hacerla más rápida'),
    ('EXPLAIN and query optimization', 'EXPLAIN only shows the syntax errors of a query', 'EXPLAIN solo muestra los errores de sintaxis de una consulta'),
    ('Transactions and isolation levels', 'ACID guarantees; levels are Read Uncommitted, Read Committed, Repeatable Read and Serializable, preventing dirty, non-repeatable and phantom reads progressively', 'Las garantías ACID; los niveles son Read Uncommitted, Read Committed, Repeatable Read y Serializable, que van evitando progresivamente los dirty reads, non-repeatable reads y phantom reads'),
    ('Transactions and isolation levels', 'There is only one isolation level, which prevents all anomalies', 'Solo existe un nivel de aislamiento, que evita todas las anomalías'),
    ('Transactions and isolation levels', 'Isolation levels control how many users can connect to the database', 'Los niveles de aislamiento controlan cuántos usuarios pueden conectarse a la base de datos'),
    ('Database normalization (1NF, 2NF, 3NF)', '1NF atomic values, 2NF no partial dependency on a composite key, 3NF no transitive dependencies; denormalize for read performance', '1FN: valores atómicos; 2FN: sin dependencia parcial de una clave compuesta; 3FN: sin dependencias transitivas; se desnormaliza por rendimiento de lectura'),
    ('Database normalization (1NF, 2NF, 3NF)', 'Normalization means putting all data into a single table', 'Normalizar significa meter todos los datos en una única tabla'),
    ('Database normalization (1NF, 2NF, 3NF)', 'Normalization is converting all text columns to lowercase', 'Normalizar es convertir todas las columnas de texto a minúsculas'),
    ('Connection pooling', 'Reusing a set of open DB connections instead of opening a new one per request, avoiding costly handshakes', 'Reutilizar un conjunto de conexiones abiertas a la base de datos en lugar de abrir una nueva por petición, evitando handshakes costosos'),
    ('Connection pooling', 'Sharing one single connection between all users with no limit', 'Compartir una única conexión entre todos los usuarios sin límite'),
    ('Connection pooling', 'Storing query results in memory to avoid hitting the database', 'Guardar los resultados de las consultas en memoria para no tener que consultar la base de datos'),
    ('CTE vs subquery', 'A CTE (WITH) names a subquery for readability and reuse, and supports recursion; simple subqueries can be fine inline', 'Una CTE (WITH) le pone nombre a una subconsulta para mayor legibilidad y reutilización, y admite recursividad; las subconsultas simples pueden estar bien en línea'),
    ('CTE vs subquery', 'CTEs are stored permanently in the database like tables', 'Las CTE se almacenan de forma permanente en la base de datos como si fueran tablas'),
    ('CTE vs subquery', 'Subqueries cannot be used inside a WHERE clause', 'Las subconsultas no se pueden usar dentro de una cláusula WHERE'),
    ('Primary key vs unique constraint', 'A PRIMARY KEY uniquely identifies each row, disallows NULLs, and a table can have only one; a UNIQUE constraint also enforces distinct values but allows NULLs (per most databases) and a table can have several.', 'Una PRIMARY KEY identifica de forma única cada fila, no permite NULL y una tabla solo puede tener una; una restricción UNIQUE también exige valores distintos pero permite NULL (según la mayoría de bases de datos) y una tabla puede tener varias.'),
    ('Primary key vs unique constraint', 'A table can have multiple primary keys but only one unique constraint.', 'Una tabla puede tener varias claves primarias pero solo una restricción unique.'),
    ('Primary key vs unique constraint', 'UNIQUE constraints are enforced only at the application level, not the database.', 'Las restricciones UNIQUE solo se aplican a nivel de aplicación, no de base de datos.'),
    ('Foreign keys', 'It enforces referential integrity by requiring a column''s values to match values in a referenced table''s primary/unique key, preventing orphaned or invalid references.', 'Garantiza la integridad referencial exigiendo que los valores de una columna coincidan con valores de la clave primaria/unique de una tabla referenciada, evitando referencias huérfanas o inválidas.'),
    ('Foreign keys', 'It automatically creates an index but enforces no validation rules.', 'Crea automáticamente un índice pero no aplica ninguna regla de validación.'),
    ('Foreign keys', 'It duplicates the referenced table''s data into the current table.', 'Duplica los datos de la tabla referenciada en la tabla actual.'),
    ('GROUP BY basics', 'It groups rows sharing the same values in specified columns into summary rows, typically used together with aggregate functions like COUNT, SUM, or AVG.', 'Agrupa las filas que comparten los mismos valores en unas columnas indicadas en filas resumen, normalmente usada junto con funciones de agregación como COUNT, SUM o AVG.'),
    ('GROUP BY basics', 'It sorts rows alphabetically by the specified column.', 'Ordena las filas alfabéticamente por la columna indicada.'),
    ('GROUP BY basics', 'It removes duplicate rows from the result set entirely.', 'Elimina por completo las filas duplicadas del resultado.'),
    ('Subquery vs JOIN performance', 'A correlated subquery that re-executes for every outer row can be much slower than a JOIN, which the query planner can often optimize with a single pass and proper index usage.', 'Una subconsulta correlacionada que se vuelve a ejecutar por cada fila externa puede ser mucho más lenta que un JOIN, que el planificador de consultas suele poder optimizar en una sola pasada usando índices adecuados.'),
    ('Subquery vs JOIN performance', 'Subqueries are always faster than JOINs in every database engine.', 'Las subconsultas siempre son más rápidas que los JOIN en cualquier motor de base de datos.'),
    ('Subquery vs JOIN performance', 'JOINs cannot be used with WHERE clauses, only subqueries can.', 'Los JOIN no se pueden usar con cláusulas WHERE, solo las subconsultas pueden.'),
    ('UNION vs UNION ALL', 'UNION combines result sets and removes duplicate rows (requiring an extra sort/dedup step); UNION ALL combines them and keeps duplicates, which is faster since no dedup is needed.', 'UNION combina los resultados y elimina las filas duplicadas (lo que exige un paso extra de ordenación/deduplicación); UNION ALL los combina conservando los duplicados, lo que es más rápido al no necesitar deduplicar.'),
    ('UNION vs UNION ALL', 'UNION ALL requires both queries to return the same number of duplicate rows.', 'UNION ALL exige que ambas consultas devuelvan el mismo número de filas duplicadas.'),
    ('UNION vs UNION ALL', 'UNION can combine columns from unrelated queries with different column counts.', 'UNION puede combinar columnas de consultas no relacionadas con distinto número de columnas.'),
    ('Self join', 'A join where a table is joined with itself (using aliases), useful for comparing rows within the same table — e.g. finding employees and their managers stored in the same employees table.', 'Un join en el que una tabla se une consigo misma (usando alias), útil para comparar filas dentro de la misma tabla, por ejemplo para relacionar empleados con sus jefes guardados en la misma tabla employees.'),
    ('Self join', 'A join that only works when a table has exactly one column.', 'Un join que solo funciona cuando una tabla tiene exactamente una columna.'),
    ('Self join', 'A special join type that automatically merges duplicate tables in a database.', 'Un tipo especial de join que fusiona automáticamente tablas duplicadas de una base de datos.'),
    ('NULL handling', 'NULL represents an unknown value, so any comparison with = against NULL evaluates to unknown (not true), never matching — you must use IS NULL / IS NOT NULL instead.', 'NULL representa un valor desconocido, así que cualquier comparación con = frente a NULL se evalúa como desconocido (no true) y nunca coincide; hay que usar IS NULL / IS NOT NULL en su lugar.'),
    ('NULL handling', 'Because NULL is treated as the empty string, not as unknown.', 'Porque NULL se trata como la cadena vacía, no como desconocido.'),
    ('NULL handling', 'It''s a syntax error in standard SQL and the query would fail to run.', 'Es un error de sintaxis en SQL estándar y la consulta fallaría al ejecutarse.'),
    ('Window functions', 'They perform a calculation across a set of rows related to the current row (a ''window'', defined with OVER/PARTITION BY) without collapsing the result into a single grouped row, unlike GROUP BY.', 'Realizan un cálculo sobre un conjunto de filas relacionadas con la fila actual (una ''ventana'', definida con OVER/PARTITION BY) sin reducir el resultado a una única fila agrupada, a diferencia de GROUP BY.'),
    ('Window functions', 'Window functions permanently reorder the physical rows in a table.', 'Las funciones de ventana reordenan de forma permanente las filas físicas de una tabla.'),
    ('Window functions', 'Window functions can only be used with the GROUP BY clause, never alone.', 'Las funciones de ventana solo se pueden usar junto con GROUP BY, nunca solas.'),
    ('UPSERT / ON CONFLICT', 'It attempts to insert a row, and if it violates a uniqueness constraint, updates the existing conflicting row instead, in a single atomic statement.', 'Intenta insertar una fila y, si viola una restricción de unicidad, actualiza en su lugar la fila existente en conflicto, todo en una única sentencia atómica.'),
    ('UPSERT / ON CONFLICT', 'It inserts a row and always fails if any constraint would be violated.', 'Inserta una fila y siempre falla si se fuera a violar alguna restricción.'),
    ('UPSERT / ON CONFLICT', 'It deletes the conflicting row and skips the insert entirely.', 'Elimina la fila en conflicto y se salta por completo la inserción.'),
    ('Database migrations', 'A migration is an incremental, scripted change to the database schema (create table, add column, etc.); version-controlling them lets a team apply schema changes consistently and roll them back if needed.', 'Una migración es un cambio incremental y con script sobre el esquema de la base de datos (crear tabla, añadir columna, etc.); versionarlas permite a un equipo aplicar cambios de esquema de forma consistente y revertirlos si hace falta.'),
    ('Database migrations', 'A migration means physically moving a database server to new hardware.', 'Una migración significa mover físicamente un servidor de base de datos a hardware nuevo.'),
    ('Database migrations', 'Migrations are only used for moving data between different database vendors.', 'Las migraciones solo se usan para mover datos entre distintos proveedores de base de datos.'),
    ('N+1 query problem', 'It happens when fetching a list of N items triggers one additional query per item to fetch related data (N extra queries); it''s avoided with a JOIN, a batched IN query, or eager loading.', 'Ocurre cuando obtener una lista de N elementos dispara una consulta adicional por elemento para traer datos relacionados (N consultas extra); se evita con un JOIN, una consulta IN en lote, o eager loading.'),
    ('N+1 query problem', 'It refers to running exactly N+1 identical queries in a transaction for safety.', 'Se refiere a ejecutar exactamente N+1 consultas idénticas en una transacción por seguridad.'),
    ('N+1 query problem', 'It''s a PostgreSQL-specific error that only occurs with more than 1 index.', 'Es un error específico de PostgreSQL que solo ocurre con más de 1 índice.'),
    ('Composite indexes', 'An index built on multiple columns together; the database can use it efficiently for queries filtering on a leading prefix of those columns (in order), but not efficiently if only a later column is filtered.', 'Un índice construido sobre varias columnas a la vez; la base de datos puede usarlo eficientemente en consultas que filtran por un prefijo inicial de esas columnas (en orden), pero no de forma eficiente si solo se filtra por una columna posterior.'),
    ('Composite indexes', 'Column order in a composite index has no effect on which queries can use it.', 'El orden de las columnas en un índice compuesto no afecta a qué consultas pueden usarlo.'),
    ('Composite indexes', 'A composite index can only ever contain exactly two columns.', 'Un índice compuesto solo puede contener exactamente dos columnas.'),
    ('Docker vs VMs', 'Containers share the host kernel, so they are lighter and start faster than VMs that each run a full guest OS', 'Los contenedores comparten el kernel del host, por lo que son más ligeros y arrancan más rápido que las VMs, que ejecutan cada una un sistema operativo invitado completo'),
    ('Docker vs VMs', 'Containers include their own kernel, which makes them more isolated than VMs', 'Los contenedores incluyen su propio kernel, lo que los hace más aislados que las VMs'),
    ('Docker vs VMs', 'VMs are always faster to start than containers', 'Las VMs siempre arrancan más rápido que los contenedores'),
    ('docker exec explained', 'It runs a command inside an already running container, e.g. docker exec -it app sh for debugging', 'Ejecuta un comando dentro de un contenedor que ya está en marcha, p. ej. docker exec -it app sh para depurar'),
    ('docker exec explained', 'It builds a new image from a Dockerfile', 'Construye una nueva imagen a partir de un Dockerfile'),
    ('docker exec explained', 'It starts a new container from an image', 'Arranca un nuevo contenedor a partir de una imagen'),
    ('Multi-stage builds', 'Use several FROM stages so build tools stay in an early stage and only the final artifacts are copied into a small runtime image', 'Usar varias etapas FROM para que las herramientas de build se queden en una etapa temprana y solo los artefactos finales se copien a una imagen de runtime pequeña'),
    ('Multi-stage builds', 'Build the same image multiple times to make it more reliable', 'Construir la misma imagen varias veces para hacerla más fiable'),
    ('Multi-stage builds', 'Run several containers from one Dockerfile at the same time', 'Ejecutar varios contenedores desde un mismo Dockerfile a la vez'),
    ('Docker networking modes', 'bridge isolates containers on one host, host shares the host network stack, overlay connects containers across multiple hosts', 'bridge aísla los contenedores en un mismo host, host comparte la pila de red del host, overlay conecta contenedores entre varios hosts'),
    ('Docker networking modes', 'All modes are equivalent; they only change the container name', 'Todos los modos son equivalentes; solo cambian el nombre del contenedor'),
    ('Docker networking modes', 'overlay is only for a single host and bridge for Swarm clusters', 'overlay es solo para un único host y bridge para clústeres Swarm'),
    ('Docker volumes vs bind mounts', 'Volumes are managed by Docker and ideal for persistent data; bind mounts map a host path and are handy in development', 'Los volúmenes los gestiona Docker y son ideales para datos persistentes; los bind mounts mapean una ruta del host y son prácticos en desarrollo'),
    ('Docker volumes vs bind mounts', 'Bind mounts are managed by Docker; volumes map any host directory', 'Los bind mounts los gestiona Docker; los volúmenes mapean cualquier directorio del host'),
    ('Docker volumes vs bind mounts', 'Neither persists data after the container is removed', 'Ninguno de los dos conserva los datos tras eliminar el contenedor'),
    ('What is a Dockerfile', 'A text file with a sequence of instructions (FROM, COPY, RUN, CMD, etc.) that Docker reads to build a reproducible image.', 'Un archivo de texto con una secuencia de instrucciones (FROM, COPY, RUN, CMD, etc.) que Docker lee para construir una imagen reproducible.'),
    ('What is a Dockerfile', 'A configuration file that only lists environment variables for a container.', 'Un archivo de configuración que solo lista variables de entorno para un contenedor.'),
    ('What is a Dockerfile', 'A compiled binary that runs containers directly without an image.', 'Un binario compilado que ejecuta contenedores directamente sin necesidad de imagen.'),
    ('CMD vs ENTRYPOINT', 'ENTRYPOINT sets the fixed executable a container always runs; CMD supplies default arguments to it (or the whole command if ENTRYPOINT isn''t set) that can be overridden at `docker run` time.', 'ENTRYPOINT fija el ejecutable que el contenedor siempre ejecuta; CMD le proporciona argumentos por defecto (o el comando completo si no hay ENTRYPOINT) que se pueden sobrescribir al hacer `docker run`.'),
    ('CMD vs ENTRYPOINT', 'CMD and ENTRYPOINT are interchangeable keywords with identical behavior.', 'CMD y ENTRYPOINT son palabras clave intercambiables con el mismo comportamiento.'),
    ('CMD vs ENTRYPOINT', 'ENTRYPOINT can only be used in the base image, never in a derived one.', 'ENTRYPOINT solo se puede usar en la imagen base, nunca en una derivada.'),
    ('.dockerignore purpose', 'It excludes specified files and directories (like node_modules or .git) from the build context sent to the Docker daemon, speeding up builds and keeping images smaller.', 'Excluye los archivos y directorios indicados (como node_modules o .git) del contexto de build que se envía al daemon de Docker, acelerando los builds y manteniendo las imágenes más pequeñas.'),
    ('.dockerignore purpose', 'It lists which Docker commands are forbidden inside the Dockerfile.', 'Lista qué comandos de Docker están prohibidos dentro del Dockerfile.'),
    ('.dockerignore purpose', 'It tells Docker which containers should never be stopped.', 'Le indica a Docker qué contenedores nunca deben detenerse.'),
    ('Image layers and caching', 'Each Dockerfile instruction creates a cached layer; if an instruction and its inputs haven''t changed since the last build, Docker reuses the cached layer instead of re-executing it, speeding up rebuilds.', 'Cada instrucción del Dockerfile crea una capa en caché; si una instrucción y sus entradas no han cambiado desde el último build, Docker reutiliza la capa en caché en lugar de volver a ejecutarla, acelerando las reconstrucciones.'),
    ('Image layers and caching', 'Every build always re-executes every instruction from scratch with no caching.', 'Cada build siempre vuelve a ejecutar todas las instrucciones desde cero, sin caché.'),
    ('Image layers and caching', 'Layers are merged into a single file before any caching can occur.', 'Las capas se fusionan en un único archivo antes de que pueda haber caché.'),
    ('docker-compose purpose', 'It lets you define and run a multi-container application (services, networks, volumes) from a single YAML file with one command, instead of manually running many `docker run` commands.', 'Permite definir y ejecutar una aplicación multi-contenedor (servicios, redes, volúmenes) desde un único archivo YAML con un solo comando, en lugar de ejecutar manualmente muchos comandos `docker run`.'),
    ('docker-compose purpose', 'It replaces Dockerfiles entirely; images are no longer needed.', 'Sustituye por completo a los Dockerfiles; ya no hacen falta imágenes.'),
    ('docker-compose purpose', 'It''s a tool exclusively for pushing images to Docker Hub.', 'Es una herramienta exclusiva para subir imágenes a Docker Hub.'),
    ('Environment variables in containers', 'With the -e flag or --env-file on `docker run`, or the environment/env_file keys in docker-compose.yml, which set process.env-style variables inside the container.', 'Con el flag -e o --env-file en `docker run`, o las claves environment/env_file en docker-compose.yml, que fijan variables al estilo process.env dentro del contenedor.'),
    ('Environment variables in containers', 'Environment variables must be baked into the image at build time and cannot be overridden.', 'Las variables de entorno deben incrustarse en la imagen en tiempo de build y no se pueden sobrescribir.'),
    ('Environment variables in containers', 'Only .env files placed inside the container''s filesystem are supported.', 'Solo se admiten archivos .env colocados dentro del sistema de archivos del contenedor.'),
    ('Docker healthcheck', 'It defines a command Docker periodically runs inside the container to determine if it''s still healthy, exposing a status (healthy/unhealthy) that orchestration tools can act on.', 'Define un comando que Docker ejecuta periódicamente dentro del contenedor para determinar si sigue sano, exponiendo un estado (healthy/unhealthy) sobre el que las herramientas de orquestación pueden actuar.'),
    ('Docker healthcheck', 'It automatically restarts the container every time it receives traffic.', 'Reinicia automáticamente el contenedor cada vez que recibe tráfico.'),
    ('Docker healthcheck', 'It checks the health of the Docker daemon on the host, not the container.', 'Comprueba el estado del daemon de Docker en el host, no del contenedor.'),
    ('Alpine vs full base images', 'Alpine images are much smaller (using musl libc and busybox), reducing image size and attack surface, though they can occasionally cause compatibility issues with native dependencies built against glibc.', 'Las imágenes Alpine son mucho más pequeñas (usan musl libc y busybox), reduciendo el tamaño de la imagen y la superficie de ataque, aunque a veces pueden causar problemas de compatibilidad con dependencias nativas compiladas contra glibc.'),
    ('Alpine vs full base images', 'Alpine images run code faster because they use a different CPU architecture.', 'Las imágenes Alpine ejecutan el código más rápido porque usan una arquitectura de CPU distinta.'),
    ('Alpine vs full base images', 'Alpine is only usable for Node.js images, not other languages.', 'Alpine solo se puede usar en imágenes de Node.js, no en otros lenguajes.'),
    ('Docker Hub vs private registry', 'When images contain proprietary code or must stay within an organization''s network/compliance boundary, a private registry (e.g. AWS ECR, GitHub Container Registry) controls who can pull them.', 'Cuando las imágenes contienen código propietario o deben permanecer dentro del perímetro de red/cumplimiento de una organización, un registro privado (p. ej. AWS ECR, GitHub Container Registry) controla quién puede descargarlas.'),
    ('Docker Hub vs private registry', 'Private registries are required for every Docker image, public or not.', 'Los registros privados son obligatorios para toda imagen Docker, sea pública o no.'),
    ('Docker Hub vs private registry', 'Docker Hub cannot host private (non-public) repositories at all.', 'Docker Hub no puede alojar en absoluto repositorios privados (no públicos).'),
    ('Docker build context', 'It''s the set of files (the specified directory and its contents) sent to the Docker daemon, which COPY/ADD instructions can reference — a large or unfiltered context slows the build.', 'Es el conjunto de archivos (el directorio indicado y su contenido) que se envía al daemon de Docker, al que pueden referirse las instrucciones COPY/ADD; un contexto grande o sin filtrar ralentiza el build.'),
    ('Docker build context', 'It refers only to the environment variables passed at build time.', 'Se refiere solo a las variables de entorno pasadas en tiempo de build.'),
    ('Docker build context', 'It''s the network context that determines which registries the build can reach.', 'Es el contexto de red que determina a qué registros puede acceder el build.'),
    ('Named vs anonymous volumes', 'A named volume has an explicit, reusable identifier that persists and can be reattached across containers; an anonymous volume gets a random ID and is harder to reference again, though Docker still manages its lifecycle.', 'Un volumen con nombre tiene un identificador explícito y reutilizable que persiste y se puede volver a asociar a otros contenedores; uno anónimo recibe un ID aleatorio y es más difícil de referenciar después, aunque Docker sigue gestionando su ciclo de vida.'),
    ('Named vs anonymous volumes', 'Anonymous volumes are always deleted immediately when the container stops.', 'Los volúmenes anónimos siempre se eliminan de inmediato al detener el contenedor.'),
    ('Named vs anonymous volumes', 'Named volumes can only be used with docker-compose, never plain docker run.', 'Los volúmenes con nombre solo se pueden usar con docker-compose, nunca con docker run a secas.'),
    ('Restart policies', 'They tell the Docker daemon whether and when to automatically restart a stopped container — useful for keeping long-running services up after crashes or a host reboot.', 'Le indican al daemon de Docker si debe reiniciar automáticamente un contenedor detenido y cuándo hacerlo; útil para mantener en marcha servicios de larga duración tras un fallo o un reinicio del host.'),
    ('Restart policies', 'They control how many CPU cores a container can restart with.', 'Controlan con cuántos núcleos de CPU puede reiniciarse un contenedor.'),
    ('Restart policies', 'They determine how often the container''s image is rebuilt.', 'Determinan con qué frecuencia se reconstruye la imagen del contenedor.'),
    ('depends_on limitations', 'By default it only controls startup order (starting a dependency''s container before the dependent one) — it does NOT wait for the dependency to be truly ready; use a healthcheck + condition: service_healthy for that.', 'Por defecto solo controla el orden de arranque (inicia el contenedor de la dependencia antes que el dependiente); NO espera a que la dependencia esté realmente lista; para eso hace falta un healthcheck + condition: service_healthy.'),
    ('depends_on limitations', 'It guarantees the dependency service has finished initializing before the dependent starts.', 'Garantiza que el servicio dependencia ha terminado de inicializarse antes de que arranque el dependiente.'),
    ('depends_on limitations', 'It automatically retries the dependent service until the dependency responds.', 'Reintenta automáticamente el servicio dependiente hasta que la dependencia responde.'),
    ('Reducing image size', 'Use a minimal base image (like Alpine), multi-stage builds to drop build-only tools, combine RUN instructions to reduce layers, and avoid copying unnecessary files (via .dockerignore).', 'Usar una imagen base mínima (como Alpine), builds multi-etapa para descartar herramientas que solo hacen falta en el build, combinar instrucciones RUN para reducir capas, y evitar copiar archivos innecesarios (mediante .dockerignore).'),
    ('Reducing image size', 'Increasing the number of RUN instructions always reduces the final image size.', 'Aumentar el número de instrucciones RUN siempre reduce el tamaño final de la imagen.'),
    ('Reducing image size', 'Image size cannot be reduced once a base image has been chosen.', 'El tamaño de la imagen no se puede reducir una vez elegida la imagen base.'),
    ('Docker vs Kubernetes', 'Docker builds and runs individual containers/images; Kubernetes is an orchestration platform that schedules, scales, and manages many containers (potentially from different runtimes) across a cluster of machines.', 'Docker construye y ejecuta contenedores/imágenes individuales; Kubernetes es una plataforma de orquestación que programa, escala y gestiona muchos contenedores (potencialmente de distintos runtimes) a través de un clúster de máquinas.'),
    ('Docker vs Kubernetes', 'Kubernetes is a newer replacement for the Dockerfile format.', 'Kubernetes es un reemplazo más moderno del formato Dockerfile.'),
    ('Docker vs Kubernetes', 'Docker and Kubernetes are competing, mutually exclusive alternatives that can never be used together.', 'Docker y Kubernetes son alternativas competidoras y mutuamente excluyentes que nunca se pueden usar juntas.'),
    ('CSS specificity', 'The weight used to decide which rule wins: inline styles > IDs > classes/attributes/pseudo-classes > elements', 'El peso que se usa para decidir qué regla gana: estilos inline > IDs > clases/atributos/pseudo-clases > elementos'),
    ('CSS specificity', 'The last rule in the file always wins regardless of selectors', 'La última regla del archivo siempre gana, sin importar los selectores'),
    ('CSS specificity', 'Element selectors always override class selectors', 'Los selectores de elemento siempre tienen prioridad sobre los de clase'),
    ('Flexbox vs Grid', 'Flexbox is for one-dimensional layouts (a row or a column); Grid is for two-dimensional layouts (rows and columns)', 'Flexbox es para layouts unidimensionales (una fila o una columna); Grid es para layouts bidimensionales (filas y columnas)'),
    ('Flexbox vs Grid', 'Grid only works for images and Flexbox only for text', 'Grid solo funciona con imágenes y Flexbox solo con texto'),
    ('Flexbox vs Grid', 'Flexbox is deprecated in favor of Grid', 'Flexbox está obsoleto a favor de Grid'),
    ('Container queries', 'They apply styles based on the size of a parent container, while media queries depend on the viewport', 'Aplican estilos según el tamaño de un contenedor padre, mientras que las media queries dependen del viewport'),
    ('Container queries', 'They query Docker containers from CSS', 'Consultan contenedores Docker desde CSS'),
    ('Container queries', 'They are the same as media queries but with a different syntax', 'Son lo mismo que las media queries pero con sintaxis distinta'),
    ('CSS containment and performance', 'The contain property tells the browser a subtree is independent, limiting the scope of layout, style and paint work', 'La propiedad contain le indica al navegador que un subárbol es independiente, limitando el alcance del trabajo de layout, estilo y pintado'),
    ('CSS containment and performance', 'contain prevents the element from ever being rendered', 'contain impide que el elemento se renderice nunca'),
    ('CSS containment and performance', 'contain forces the browser to repaint the whole page on changes', 'contain obliga al navegador a repintar toda la página en cada cambio'),
    ('The box model', 'Content, padding, border, and margin.', 'Contenido, padding, border y margin.'),
    ('The box model', 'Content, margin, border, and padding.', 'Contenido, margin, border y padding.'),
    ('The box model', 'Border, content, margin, and padding.', 'Border, contenido, margin y padding.'),
    ('position property values', 'relative positions an element relative to its own normal position; absolute positions it relative to its nearest positioned ancestor; fixed positions it relative to the viewport, staying in place when scrolling.', 'relative posiciona un elemento respecto a su propia posición normal; absolute lo posiciona respecto a su ancestro posicionado más cercano; fixed lo posiciona respecto al viewport, quedándose fijo al hacer scroll.'),
    ('position property values', 'All three values behave identically except for their default z-index.', 'Los tres valores se comportan igual salvo por su z-index por defecto.'),
    ('position property values', 'fixed positions an element relative to its parent, absolute relative to the viewport.', 'fixed posiciona un elemento respecto a su padre, absolute respecto al viewport.'),
    ('z-index and stacking context', 'z-index only affects positioned elements (position other than static) and is evaluated within a stacking context — a higher z-index in one context can still render below a lower z-index in a different, higher-level stacking context.', 'z-index solo afecta a elementos posicionados (position distinto de static) y se evalúa dentro de un contexto de apilamiento; un z-index más alto en un contexto puede seguir renderizándose por debajo de uno más bajo en otro contexto de nivel superior.'),
    ('z-index and stacking context', 'z-index works on every element regardless of its position value.', 'z-index funciona en cualquier elemento sin importar su valor de position.'),
    ('z-index and stacking context', 'z-index is a global value compared across the entire page with no notion of context.', 'z-index es un valor global que se compara en toda la página sin noción de contexto.'),
    ('CSS custom properties', 'Defined with --name: value (often on :root) and read with var(--name), they let you reuse and dynamically update values across a stylesheet, including via JavaScript.', 'Se definen con --nombre: valor (a menudo en :root) y se leen con var(--nombre); permiten reutilizar y actualizar valores dinámicamente en una hoja de estilos, incluso desde JavaScript.'),
    ('CSS custom properties', 'They are compiled away at build time and cannot be changed at runtime.', 'Desaparecen al compilar y no se pueden cambiar en tiempo de ejecución.'),
    ('CSS custom properties', 'They can only store color values, not other CSS value types.', 'Solo pueden almacenar valores de color, no otros tipos de valor CSS.'),
    ('Media queries', 'A conditional CSS block (e.g. @media (max-width: 768px)) that applies styles only when the specified conditions (like viewport width) are met — the basis of responsive design.', 'Un bloque CSS condicional (p. ej. @media (max-width: 768px)) que aplica estilos solo cuando se cumplen las condiciones indicadas (como el ancho del viewport); la base del diseño responsive.'),
    ('Media queries', 'A query language for fetching data from a CSS-in-JS backend.', 'Un lenguaje de consulta para traer datos de un backend CSS-in-JS.'),
    ('Media queries', 'A way to detect which fonts are installed on the user''s device.', 'Una forma de detectar qué fuentes tiene instaladas el dispositivo del usuario.'),
    ('rem vs em', 'rem is always relative to the root (html) element''s font size; em is relative to the font size of the current element (or its parent for some properties), so em values can compound in nested elements.', 'rem siempre es relativo al tamaño de fuente del elemento raíz (html); em es relativo al tamaño de fuente del elemento actual (o de su padre en algunas propiedades), así que los valores em se pueden ir acumulando en elementos anidados.'),
    ('rem vs em', 'rem and em are identical; rem is just newer syntax.', 'rem y em son idénticos; rem es solo una sintaxis más nueva.'),
    ('rem vs em', 'em is relative to the viewport width, rem is relative to the viewport height.', 'em es relativo al ancho del viewport, rem es relativo a la altura del viewport.'),
    ('BEM naming convention', 'It gives class names a predictable structure (block__element--modifier) to avoid specificity conflicts and make relationships between markup and styles explicit in large codebases.', 'Da a los nombres de clase una estructura predecible (block__element--modifier) para evitar conflictos de especificidad y hacer explícitas las relaciones entre el markup y los estilos en bases de código grandes.'),
    ('BEM naming convention', 'BEM is a CSS preprocessor like Sass, converting variables into static values.', 'BEM es un preprocesador CSS como Sass, que convierte variables en valores estáticos.'),
    ('BEM naming convention', 'BEM automatically minifies and compresses class names for production.', 'BEM minifica y comprime automáticamente los nombres de clase para producción.'),
    ('Grid template areas', 'It lets you name regions of a grid layout visually (as a string map) and place items into them with grid-area, making complex layouts more readable than counting rows/columns.', 'Permite nombrar visualmente las regiones de un layout de grid (como un mapa de strings) y colocar elementos en ellas con grid-area, haciendo que los layouts complejos sean más legibles que contar filas/columnas.'),
    ('Grid template areas', 'It''s used to define animation keyframes for grid items.', 'Se usa para definir los keyframes de animación de los elementos del grid.'),
    ('Grid template areas', 'It automatically generates a grid layout from an array of JSON data.', 'Genera automáticamente un layout de grid a partir de un array de datos JSON.'),
    ('Pseudo-classes vs pseudo-elements', 'A pseudo-class (single colon, e.g. :hover) selects an element in a particular state; a pseudo-element (double colon, e.g. ::before) targets a sub-part of an element that doesn''t exist as a separate DOM node.', 'Una pseudo-clase (un solo dos puntos, p. ej. :hover) selecciona un elemento en un estado concreto; un pseudo-elemento (doble dos puntos, p. ej. ::before) apunta a una subparte de un elemento que no existe como nodo del DOM independiente.'),
    ('Pseudo-classes vs pseudo-elements', 'Pseudo-elements select element states; pseudo-classes create new DOM nodes.', 'Los pseudo-elementos seleccionan estados de un elemento; las pseudo-clases crean nuevos nodos del DOM.'),
    ('Pseudo-classes vs pseudo-elements', 'They are the same feature, and the number of colons has no meaning.', 'Son la misma funcionalidad, y el número de dos puntos no tiene ningún significado.'),
    ('Transitions vs animations', 'A transition smoothly interpolates a property between two states triggered by a change (like :hover); an animation uses @keyframes to define multiple steps and can run automatically, loop, and control timing independent of a state change.', 'Una transición interpola suavemente una propiedad entre dos estados provocados por un cambio (como :hover); una animación usa @keyframes para definir varios pasos y puede ejecutarse automáticamente, repetirse en bucle y controlar el tiempo de forma independiente a un cambio de estado.'),
    ('Transitions vs animations', 'Transitions require JavaScript to trigger; animations run purely in CSS.', 'Las transiciones necesitan JavaScript para dispararse; las animaciones se ejecutan puramente en CSS.'),
    ('Transitions vs animations', 'Animations can only run once, transitions can loop indefinitely.', 'Las animaciones solo se pueden ejecutar una vez, las transiciones pueden repetirse indefinidamente.'),
    ('will-change property', 'It hints to the browser that a property is about to change, letting it optimize ahead of time (e.g. promoting the element to its own compositor layer) — but overusing it can hurt performance by consuming excess memory.', 'Le indica al navegador que una propiedad está a punto de cambiar, permitiéndole optimizar por adelantado (p. ej. promocionando el elemento a su propia capa del compositor); pero abusar de ella puede perjudicar el rendimiento por consumir memoria de más.'),
    ('will-change property', 'It permanently disables all future changes to that CSS property.', 'Desactiva de forma permanente todos los cambios futuros de esa propiedad CSS.'),
    ('will-change property', 'It forces a synchronous reflow before every animation frame.', 'Fuerza un reflow síncrono antes de cada fotograma de animación.'),
    ('The clamp() function', 'clamp(min, preferred, max) returns a value that scales with the preferred expression (often based on viewport units) but never goes below min or above max — useful for fluid, responsive typography.', 'clamp(min, preferido, max) devuelve un valor que escala según la expresión preferida (a menudo basada en unidades de viewport) pero nunca baja de min ni supera max; útil para tipografía fluida y responsive.'),
    ('The clamp() function', 'It rounds a value to the nearest integer.', 'Redondea un valor al entero más cercano.'),
    ('The clamp() function', 'It restricts an element to a fixed aspect ratio.', 'Restringe un elemento a una relación de aspecto fija.'),
    ('CSS Modules', 'They scope class names to the specific component file by generating unique class names at build time, avoiding global class name collisions common in plain CSS.', 'Limitan el alcance de los nombres de clase al archivo del componente generando nombres de clase únicos en tiempo de build, evitando las colisiones globales de nombres habituales en CSS puro.'),
    ('CSS Modules', 'CSS Modules replace CSS entirely with a JavaScript-only styling API.', 'Los CSS Modules sustituyen por completo a CSS con una API de estilos solo en JavaScript.'),
    ('CSS Modules', 'CSS Modules are a runtime library that must be shipped to the browser.', 'Los CSS Modules son una librería en tiempo de ejecución que hay que enviar al navegador.'),
    ('The :root selector', 'It matches the document''s root element (<html>), and since it has the highest specificity among element-level selectors and is always present, it''s the conventional place to declare global custom properties.', 'Coincide con el elemento raíz del documento (<html>), y como tiene la mayor especificidad entre los selectores de elemento y siempre está presente, es el lugar habitual para declarar propiedades personalizadas globales.'),
    ('The :root selector', ':root selects every top-level child of the <body> element.', ':root selecciona todos los hijos de primer nivel del elemento <body>.'),
    ('The :root selector', ':root only works inside CSS Modules, not plain stylesheets.', ':root solo funciona dentro de CSS Modules, no en hojas de estilo normales.'),
    ('CSS cascade layers', 'They let you explicitly control the order in which groups of styles are applied regardless of selector specificity or source order, making it easier to manage precedence between resets, frameworks, and component styles.', 'Permiten controlar explícitamente el orden en que se aplican grupos de estilos, sin importar la especificidad del selector ni el orden de origen, facilitando gestionar la precedencia entre resets, frameworks y estilos de componentes.'),
    ('CSS cascade layers', '@layer creates isolated iframes for each stylesheet.', '@layer crea iframes aislados para cada hoja de estilos.'),
    ('CSS cascade layers', '@layer is used exclusively to define print stylesheets.', '@layer se usa exclusivamente para definir hojas de estilo de impresión.'),
    ('prefers-color-scheme', 'Whether the user has requested a light or dark color theme at the OS/browser level, letting a stylesheet adapt automatically with @media (prefers-color-scheme: dark).', 'Si el usuario ha pedido un tema claro u oscuro a nivel de sistema operativo/navegador, permitiendo que una hoja de estilos se adapte automáticamente con @media (prefers-color-scheme: dark).'),
    ('prefers-color-scheme', 'Whether the user''s monitor supports more than 16 million colors.', 'Si el monitor del usuario admite más de 16 millones de colores.'),
    ('prefers-color-scheme', 'Whether the page is being printed in color or grayscale.', 'Si la página se está imprimiendo en color o en escala de grises.'),
    ('Reverse a linked list', 'Iterate once keeping prev, current and next pointers, pointing each node back to prev: O(n) time, O(1) space', 'Recorrerla una vez manteniendo los punteros prev, current y next, haciendo que cada nodo apunte hacia atrás a prev: O(n) en tiempo, O(1) en espacio'),
    ('Reverse a linked list', 'Sort the nodes in descending order: O(n log n)', 'Ordenar los nodos de forma descendente: O(n log n)'),
    ('Reverse a linked list', 'Copy the values into a new list for every node: O(n^2)', 'Copiar los valores a una lista nueva para cada nodo: O(n^2)'),
    ('Big-O of binary search', 'O(log n), because the search space is halved at every step (on a sorted collection)', 'O(log n), porque el espacio de búsqueda se reduce a la mitad en cada paso (sobre una colección ordenada)'),
    ('Big-O of binary search', 'O(n), because every element is checked once', 'O(n), porque se comprueba cada elemento una vez'),
    ('Big-O of binary search', 'O(1), because it jumps directly to the middle', 'O(1), porque salta directamente al medio'),
    ('Implement a stack with arrays', 'Use push to add and pop to remove from the end of the array, both O(1) (LIFO)', 'Usar push para añadir y pop para quitar por el final del array, ambas O(1) (LIFO)'),
    ('Implement a stack with arrays', 'Use push to add and shift to remove from the front (FIFO)', 'Usar push para añadir y shift para quitar por el principio (FIFO)'),
    ('Implement a stack with arrays', 'Sort the array after every insertion', 'Ordenar el array después de cada inserción'),
    ('LRU Cache implementation', 'A hash map pointing to nodes of a doubly linked list ordered by recency gives O(1) get and put', 'Un hash map que apunta a nodos de una lista doblemente enlazada ordenada por uso reciente da get y put en O(1)'),
    ('LRU Cache implementation', 'A sorted array scanned on every get, giving O(n log n)', 'Un array ordenado que se recorre en cada get, dando O(n log n)'),
    ('LRU Cache implementation', 'A plain array where the oldest item is found with a linear search', 'Un array normal donde el elemento más antiguo se busca de forma lineal'),
    ('Detect a cycle in a linked list', 'Floyd: move a slow pointer by 1 and a fast pointer by 2; if they meet there is a cycle (O(1) space)', 'Floyd: mover un puntero lento de 1 en 1 y uno rápido de 2 en 2; si se encuentran, hay un ciclo (O(1) en espacio)'),
    ('Detect a cycle in a linked list', 'Sort the list and check for duplicate values', 'Ordenar la lista y comprobar si hay valores duplicados'),
    ('Detect a cycle in a linked list', 'Count the nodes; if the count is odd there is a cycle', 'Contar los nodos; si el conteo es impar, hay un ciclo'),
    ('Two-pointer technique', 'Using two indices that move through a data structure (often from opposite ends or at different speeds) to solve problems like finding pairs in a sorted array in O(n) instead of O(n^2).', 'Usar dos índices que recorren una estructura de datos (a menudo desde extremos opuestos o a velocidades distintas) para resolver problemas como encontrar pares en un array ordenado en O(n) en vez de O(n^2).'),
    ('Two-pointer technique', 'A technique that requires two separate arrays to be sorted independently.', 'Una técnica que requiere ordenar dos arrays por separado de forma independiente.'),
    ('Two-pointer technique', 'A debugging technique for tracking two variables in a debugger.', 'Una técnica de depuración para seguir dos variables en un debugger.'),
    ('Sliding window technique', 'Maintaining a contiguous subrange (window) over an array or string that expands/contracts as you scan, avoiding recomputation from scratch — used for problems like longest substring without repeating characters.', 'Mantener un subrango contiguo (ventana) sobre un array o cadena que se expande/contrae mientras se recorre, evitando recalcular desde cero; se usa en problemas como la subcadena más larga sin caracteres repetidos.'),
    ('Sliding window technique', 'It''s a UI pattern for scrolling panels, unrelated to algorithms.', 'Es un patrón de UI para paneles con scroll, sin relación con algoritmos.'),
    ('Sliding window technique', 'It requires sorting the input array first before it can be applied.', 'Requiere ordenar antes el array de entrada para poder aplicarse.'),
    ('Tree traversal orders', 'In-order visits left, node, right (yields sorted order for a BST); pre-order visits node, left, right; post-order visits left, right, node.', 'In-order visita izquierda, nodo, derecha (da orden ascendente en un BST); pre-order visita nodo, izquierda, derecha; post-order visita izquierda, derecha, nodo.'),
    ('Tree traversal orders', 'They all visit nodes in the exact same order but differ only in return type.', 'Los tres visitan los nodos exactamente en el mismo orden y solo difieren en el tipo de retorno.'),
    ('Tree traversal orders', 'Pre-order is only valid for balanced trees, the others work on any tree.', 'Pre-order solo es válido para árboles balanceados, los demás funcionan en cualquier árbol.'),
    ('BFS vs DFS', 'BFS explores a graph level by level using a queue, finding the shortest path in unweighted graphs; DFS explores as far as possible down one branch before backtracking, typically using a stack or recursion.', 'BFS explora un grafo nivel a nivel usando una cola, encontrando el camino más corto en grafos sin peso; DFS explora lo más lejos posible por una rama antes de retroceder, normalmente usando una pila o recursividad.'),
    ('BFS vs DFS', 'BFS uses recursion and DFS uses a queue.', 'BFS usa recursividad y DFS usa una cola.'),
    ('BFS vs DFS', 'BFS and DFS are only applicable to trees, never general graphs.', 'BFS y DFS solo se aplican a árboles, nunca a grafos generales.'),
    ('Merge sort', 'It recursively splits the array in half until single elements remain, then merges sorted halves back together; this runs in O(n log n) time in all cases and is stable.', 'Divide recursivamente el array a la mitad hasta quedarse con elementos individuales, y luego fusiona las mitades ordenadas; se ejecuta en O(n log n) en todos los casos y es estable.'),
    ('Merge sort', 'It repeatedly swaps adjacent out-of-order elements until the array is sorted.', 'Va intercambiando repetidamente elementos adyacentes desordenados hasta ordenar el array.'),
    ('Merge sort', 'It picks a pivot and partitions elements around it, like quicksort.', 'Elige un pivote y particiona los elementos a su alrededor, como quicksort.'),
    ('Quicksort', 'It picks a pivot, partitions elements into those less than and greater than the pivot, and recursively sorts each partition; average case is O(n log n), but worst case (e.g. an already-sorted array with a poor pivot choice) is O(n^2).', 'Elige un pivote, reparte los elementos entre los menores y mayores que el pivote, y ordena cada partición recursivamente; el caso medio es O(n log n), pero el peor caso (p. ej. un array ya ordenado con una mala elección de pivote) es O(n^2).'),
    ('Quicksort', 'Quicksort''s worst case is always O(n log n), same as its average case.', 'El peor caso de quicksort siempre es O(n log n), igual que su caso medio.'),
    ('Quicksort', 'Quicksort merges two pre-sorted halves, like merge sort.', 'Quicksort fusiona dos mitades previamente ordenadas, como merge sort.'),
    ('Hash collisions', 'Common strategies are chaining (each slot holds a list of entries) and open addressing (probing for the next free slot), both letting multiple keys coexist despite a collision.', 'Las estrategias habituales son el encadenamiento (cada slot contiene una lista de entradas) y el direccionamiento abierto (buscar el siguiente slot libre), que permiten que varias claves coexistan a pesar de la colisión.'),
    ('Hash collisions', 'Hash tables reject the second key and the insertion silently fails.', 'Las tablas hash rechazan la segunda clave y la inserción falla en silencio.'),
    ('Hash collisions', 'Collisions can never happen because hash functions guarantee unique outputs.', 'Las colisiones nunca pueden ocurrir porque las funciones hash garantizan salidas únicas.'),
    ('Dynamic programming basics', 'Optimal substructure (the optimal solution can be built from optimal solutions to subproblems) and overlapping subproblems (the same subproblems recur, so caching/memoizing their results avoids redundant work).', 'Subestructura óptima (la solución óptima se puede construir a partir de soluciones óptimas de subproblemas) y subproblemas solapados (los mismos subproblemas se repiten, así que cachear/memoizar sus resultados evita trabajo redundante).'),
    ('Dynamic programming basics', 'The input must already be sorted and the problem must be a graph problem.', 'La entrada debe estar ya ordenada y el problema debe ser un problema de grafos.'),
    ('Dynamic programming basics', 'The problem must have exactly one valid solution with no alternatives.', 'El problema debe tener exactamente una solución válida, sin alternativas.'),
    ('Recursion vs iteration', 'Recursion can be more readable for naturally recursive problems (like tree traversal) but risks stack overflow and extra call-stack overhead; iteration avoids that overhead but can be less intuitive to express.', 'La recursividad puede ser más legible en problemas naturalmente recursivos (como recorrer un árbol) pero arriesga un stack overflow y sobrecarga extra de la pila de llamadas; la iteración evita esa sobrecarga pero puede ser menos intuitiva de expresar.'),
    ('Recursion vs iteration', 'Recursive solutions always run faster than iterative ones.', 'Las soluciones recursivas siempre se ejecutan más rápido que las iterativas.'),
    ('Recursion vs iteration', 'Iterative solutions cannot solve any problem that recursion can solve.', 'Las soluciones iterativas no pueden resolver ningún problema que la recursividad pueda resolver.'),
    ('Array vs linked list complexity', 'Arrays offer O(1) indexed access but O(n) insertion/deletion in the middle (due to shifting); linked lists offer O(1) insertion/deletion once you have a reference to the node but O(n) access by index.', 'Los arrays ofrecen acceso indexado en O(1) pero inserción/borrado en el medio en O(n) (por el desplazamiento); las listas enlazadas ofrecen inserción/borrado en O(1) una vez que tienes referencia al nodo, pero acceso por índice en O(n).'),
    ('Array vs linked list complexity', 'Arrays and linked lists have identical time complexity for every operation.', 'Los arrays y las listas enlazadas tienen la misma complejidad temporal en todas las operaciones.'),
    ('Array vs linked list complexity', 'Linked lists always outperform arrays for every use case.', 'Las listas enlazadas siempre rinden mejor que los arrays en cualquier caso de uso.'),
    ('Find the missing number', 'Compute the expected sum of 1..n using the formula n*(n+1)/2, subtract the actual sum of the array — the difference is the missing number, in O(n) time and O(1) space.', 'Calcula la suma esperada de 1..n con la fórmula n*(n+1)/2, réstale la suma real del array; la diferencia es el número que falta, en O(n) de tiempo y O(1) de espacio.'),
    ('Find the missing number', 'You must sort the array first, which takes O(n log n) at minimum.', 'Hay que ordenar antes el array, lo que cuesta como mínimo O(n log n).'),
    ('Find the missing number', 'It''s only possible by checking every number from 1 to n against the array, in O(n^2).', 'Solo es posible comprobando cada número de 1 a n contra el array, en O(n^2).'),
    ('Valid parentheses', 'Push opening brackets onto a stack; on a closing bracket, check it matches the top of the stack (popping it) — the string is valid if the stack ends empty.', 'Apila los corchetes de apertura en una pila; al encontrar uno de cierre, comprueba que coincide con el que hay en la cima (y lo saca); la cadena es válida si la pila termina vacía.'),
    ('Valid parentheses', 'Count the total number of opening and closing brackets and check they''re equal.', 'Contar el número total de corchetes de apertura y cierre y comprobar que son iguales.'),
    ('Valid parentheses', 'Reverse the string and check it reads the same forwards and backwards.', 'Invertir la cadena y comprobar que se lee igual hacia delante y hacia atrás.'),
    ('Binary search tree properties', 'For every node, all values in its left subtree must be smaller and all values in its right subtree must be larger than the node''s own value.', 'Para cada nodo, todos los valores de su subárbol izquierdo deben ser menores y todos los de su subárbol derecho deben ser mayores que el valor del propio nodo.'),
    ('Binary search tree properties', 'Every node must have exactly two children, or the tree is invalid.', 'Cada nodo debe tener exactamente dos hijos, o el árbol no es válido.'),
    ('Binary search tree properties', 'The tree must always be perfectly balanced to be considered a valid BST.', 'El árbol siempre debe estar perfectamente balanceado para considerarse un BST válido.'),
    ('Graph representations', 'An adjacency list uses O(V+E) space and is efficient for sparse graphs; an adjacency matrix uses O(V^2) space but gives O(1) edge-existence checks, better suited to dense graphs.', 'Una lista de adyacencia usa O(V+E) de espacio y es eficiente para grafos dispersos; una matriz de adyacencia usa O(V^2) de espacio pero permite comprobar si existe una arista en O(1), más adecuada para grafos densos.'),
    ('Graph representations', 'Adjacency matrices always use less memory than adjacency lists.', 'Las matrices de adyacencia siempre usan menos memoria que las listas de adyacencia.'),
    ('Graph representations', 'Adjacency lists cannot represent directed graphs, only undirected ones.', 'Las listas de adyacencia no pueden representar grafos dirigidos, solo no dirigidos.'),
    ('Kadane''s algorithm', 'It finds the maximum sum of a contiguous subarray in O(n) time by tracking the best sum ending at the current position, resetting to the current element whenever the running sum would go negative.', 'Encuentra la suma máxima de un subarray contiguo en O(n) llevando la mejor suma que termina en la posición actual, reiniciándola al elemento actual cada vez que la suma acumulada se volvería negativa.'),
    ('Kadane''s algorithm', 'It finds the shortest path between two nodes in a weighted graph.', 'Encuentra el camino más corto entre dos nodos en un grafo con pesos.'),
    ('Kadane''s algorithm', 'It sorts an array in O(n) time using bucket sort.', 'Ordena un array en O(n) usando bucket sort.'),
    ('Design a URL shortener', 'Generate unique IDs encoded in base62, store id to URL in a key-value store, cache hot links and redirect with 301/302', 'Generar IDs únicos codificados en base62, guardar el mapeo id-URL en un almacén clave-valor, cachear los enlaces populares y redirigir con 301/302'),
    ('Design a URL shortener', 'Store every URL in a single text file and scan it on each request', 'Guardar todas las URLs en un único archivo de texto y recorrerlo en cada petición'),
    ('Design a URL shortener', 'Encrypt the long URL and use the ciphertext as the short code', 'Cifrar la URL larga y usar el texto cifrado como código corto'),
    ('Design a rate limiter', 'Token bucket allows bursts at a steady refill rate; sliding window is more accurate than fixed window, usually backed by Redis', 'Token bucket permite ráfagas con una tasa de recarga constante; sliding window es más preciso que fixed window, normalmente respaldado por Redis'),
    ('Design a rate limiter', 'Block every client after their first request', 'Bloquear a todos los clientes después de su primera petición'),
    ('Design a rate limiter', 'Fixed window is always the most accurate algorithm', 'Fixed window siempre es el algoritmo más preciso'),
    ('Caching strategies (cache-aside, write-through)', 'Cache-aside loads on miss from the app; write-through writes cache and DB together; write-back writes the DB later', 'Cache-aside carga desde la app cuando hay un fallo de caché; write-through escribe a la vez en caché y BD; write-back escribe en la BD más tarde'),
    ('Caching strategies (cache-aside, write-through)', 'Write-through never writes to the database', 'Write-through nunca escribe en la base de datos'),
    ('Caching strategies (cache-aside, write-through)', 'Cache-aside means the database updates the cache automatically', 'Cache-aside significa que la base de datos actualiza la caché automáticamente'),
    ('Horizontal vs vertical scaling', 'Horizontal adds more machines behind a load balancer; vertical adds more CPU/RAM to one machine', 'El horizontal añade más máquinas detrás de un balanceador de carga; el vertical añade más CPU/RAM a una única máquina'),
    ('Horizontal vs vertical scaling', 'Vertical scaling adds more machines; horizontal upgrades one machine', 'El escalado vertical añade más máquinas; el horizontal mejora una única máquina'),
    ('Horizontal vs vertical scaling', 'Both mean the same thing', 'Ambos significan lo mismo'),
    ('CAP theorem', 'During a network partition a distributed system must choose between consistency and availability; eventual consistency means replicas converge over time', 'Durante una partición de red, un sistema distribuido debe elegir entre consistencia y disponibilidad; la consistencia eventual significa que las réplicas convergen con el tiempo'),
    ('CAP theorem', 'A system can always guarantee consistency, availability and partition tolerance at once', 'Un sistema siempre puede garantizar consistencia, disponibilidad y tolerancia a particiones a la vez'),
    ('CAP theorem', 'CAP stands for Cache, API and Performance', 'CAP son las siglas de Cache, API y Performance'),
    ('Design a real-time chat system', 'Use WebSockets for persistent connections, a message broker/pub-sub to fan out between servers, and per-conversation ordering', 'Usar WebSockets para conexiones persistentes, un broker de mensajes/pub-sub para distribuir entre servidores, y mantener el orden por conversación'),
    ('Design a real-time chat system', 'Poll the server every minute with full page reloads', 'Consultar al servidor cada minuto recargando la página entera'),
    ('Design a real-time chat system', 'Send messages by email between users', 'Enviar los mensajes por email entre usuarios'),
    ('Load balancer algorithms', 'Round robin cycles through servers evenly; least connections routes to the server with fewest active connections; consistent hashing routes based on a key so the same client tends to hit the same server.', 'Round robin va rotando por los servidores de forma equitativa; least connections dirige al servidor con menos conexiones activas; consistent hashing enruta según una clave, de forma que el mismo cliente tiende a caer en el mismo servidor.'),
    ('Load balancer algorithms', 'Load balancers only support randomly picking a server with no other strategy.', 'Los balanceadores de carga solo admiten elegir un servidor al azar, sin otra estrategia.'),
    ('Load balancer algorithms', 'All load balancing algorithms guarantee perfectly equal CPU usage across servers.', 'Todos los algoritmos de balanceo garantizan un uso de CPU perfectamente igual entre servidores.'),
    ('Database sharding', 'Splitting a large dataset across multiple database instances (shards), typically by a shard key, to scale writes and storage horizontally — it introduces challenges like cross-shard queries/joins and rebalancing.', 'Dividir un conjunto de datos grande entre varias instancias de base de datos (shards), normalmente según una shard key, para escalar escrituras y almacenamiento horizontalmente; introduce desafíos como consultas/joins entre shards y el rebalanceo.'),
    ('Database sharding', 'Sharding means creating read replicas of the exact same data on every server.', 'El sharding consiste en crear réplicas de lectura con exactamente los mismos datos en cada servidor.'),
    ('Database sharding', 'Sharding is a caching technique that has nothing to do with data storage.', 'El sharding es una técnica de caché que no tiene nada que ver con el almacenamiento de datos.'),
    ('Master-replica replication', 'Synchronous replication waits for the replica to confirm the write before acknowledging success (strong consistency, higher latency); asynchronous replication acknowledges immediately and replicates in the background (lower latency, risk of data loss on failover).', 'La replicación síncrona espera a que la réplica confirme la escritura antes de dar por buena la operación (consistencia fuerte, más latencia); la asíncrona confirma de inmediato y replica en segundo plano (menor latencia, riesgo de pérdida de datos en un failover).'),
    ('Master-replica replication', 'Synchronous replication is always slower and provides no consistency guarantee.', 'La replicación síncrona siempre es más lenta y no ofrece ninguna garantía de consistencia.'),
    ('Master-replica replication', 'Asynchronous replication guarantees zero data loss during a failover.', 'La replicación asíncrona garantiza cero pérdida de datos durante un failover.'),
    ('Message queues', 'To decouple producers from consumers, buffer bursts of traffic, enable asynchronous processing, and allow consumers to fail or scale independently without losing messages.', 'Para desacoplar a los productores de los consumidores, absorber picos de tráfico, permitir el procesamiento asíncrono, y que los consumidores puedan fallar o escalar de forma independiente sin perder mensajes.'),
    ('Message queues', 'Message queues are only useful for sending emails, not general service communication.', 'Las colas de mensajes solo sirven para enviar emails, no para la comunicación general entre servicios.'),
    ('Message queues', 'A message queue guarantees messages are always processed in under 1ms.', 'Una cola de mensajes garantiza que los mensajes siempre se procesan en menos de 1ms.'),
    ('Idempotency in APIs', 'An idempotent endpoint produces the same result no matter how many times the same request is retried (e.g. using an idempotency key), preventing duplicate side effects like double-charging on network retries.', 'Un endpoint idempotente produce el mismo resultado sin importar cuántas veces se reintente la misma petición (p. ej. usando una idempotency key), evitando efectos secundarios duplicados como cobrar dos veces por un reintento de red.'),
    ('Idempotency in APIs', 'Idempotency means the endpoint can never be called more than once, ever.', 'La idempotencia significa que el endpoint nunca se puede llamar más de una vez, jamás.'),
    ('Idempotency in APIs', 'Idempotency only matters for GET requests, never for POST or PUT.', 'La idempotencia solo importa en peticiones GET, nunca en POST o PUT.'),
    ('API Gateway pattern', 'It''s a single entry point that routes client requests to the right backend service, and commonly handles cross-cutting concerns like authentication, rate limiting, and request/response transformation.', 'Es un único punto de entrada que enruta las peticiones del cliente al servicio backend adecuado, y suele encargarse de aspectos transversales como autenticación, rate limiting y transformación de petición/respuesta.'),
    ('API Gateway pattern', 'It replaces the need for individual services to have their own databases.', 'Elimina la necesidad de que cada servicio tenga su propia base de datos.'),
    ('API Gateway pattern', 'It''s used only for serving static frontend assets, not API traffic.', 'Solo se usa para servir assets estáticos del frontend, no tráfico de API.'),
    ('Microservices vs monolith', 'Microservices allow independent deployment and scaling of services at the cost of operational complexity (network calls, distributed data, observability); a monolith is simpler to develop and deploy but scales and deploys as one unit.', 'Los microservicios permiten desplegar y escalar servicios de forma independiente a costa de complejidad operativa (llamadas de red, datos distribuidos, observabilidad); un monolito es más sencillo de desarrollar y desplegar pero escala y se despliega como una sola unidad.'),
    ('Microservices vs monolith', 'Microservices always have better performance than a monolith for every workload.', 'Los microservicios siempre tienen mejor rendimiento que un monolito en cualquier carga de trabajo.'),
    ('Microservices vs monolith', 'A monolith cannot be scaled horizontally under any circumstances.', 'Un monolito no se puede escalar horizontalmente bajo ninguna circunstancia.'),
    ('Consistent hashing', 'When servers are added or removed, consistent hashing minimizes the number of keys that need to be remapped (only a fraction, not all of them), unlike simple modulo hashing which reshuffles almost everything.', 'Cuando se añaden o quitan servidores, el consistent hashing minimiza el número de claves que hay que remapear (solo una fracción, no todas), a diferencia del hashing por módulo simple, que reordena casi todo.'),
    ('Consistent hashing', 'It guarantees every server holds exactly the same number of keys at all times.', 'Garantiza que cada servidor tenga siempre exactamente el mismo número de claves.'),
    ('Consistent hashing', 'It''s a technique for compressing hash values to save memory.', 'Es una técnica para comprimir valores hash y ahorrar memoria.'),
    ('CDN purpose', 'A Content Delivery Network caches and serves content from servers geographically close to users, reducing latency and offloading traffic from the origin server.', 'Una red de distribución de contenidos (CDN) cachea y sirve contenido desde servidores geográficamente cercanos a los usuarios, reduciendo la latencia y aliviando el tráfico del servidor de origen.'),
    ('CDN purpose', 'A CDN is a database that replicates data for stronger consistency guarantees.', 'Un CDN es una base de datos que replica datos para dar garantías de consistencia más fuertes.'),
    ('CDN purpose', 'A CDN only works for video content, not images, scripts, or HTML.', 'Un CDN solo funciona con contenido de vídeo, no con imágenes, scripts o HTML.'),
    ('Designing a notification system', 'A queue to buffer and decouple notification events, worker services to fan out to different channels (push, email, SMS), user preference/subscription storage, and retry/dead-letter handling for failed deliveries.', 'Una cola para amortiguar y desacoplar los eventos de notificación, servicios worker para distribuir hacia distintos canales (push, email, SMS), almacenamiento de preferencias/suscripciones de usuario, y manejo de reintentos/dead-letter para los envíos fallidos.'),
    ('Designing a notification system', 'A single synchronous HTTP call made directly from the application to every user''s device.', 'Una única llamada HTTP síncrona hecha directamente desde la aplicación a cada dispositivo de usuario.'),
    ('Designing a notification system', 'Notifications should always be stored only in the client app''s local storage.', 'Las notificaciones siempre deberían guardarse solo en el almacenamiento local de la app del cliente.'),
    ('Designing a news feed', 'Fan-out on write pre-computes and pushes new posts into each follower''s feed immediately (fast reads, expensive for celebrities with huge followings); fan-out on read computes the feed at request time by pulling from followed users (cheaper writes, slower reads).', 'El fan-out en escritura precalcula y empuja las publicaciones nuevas al feed de cada seguidor de inmediato (lecturas rápidas, costoso para cuentas con muchísimos seguidores); el fan-out en lectura calcula el feed en el momento de la petición trayendo datos de los usuarios seguidos (escrituras más baratas, lecturas más lentas).'),
    ('Designing a news feed', 'News feeds must always be computed entirely at read time with no caching.', 'Los feeds de noticias siempre deben calcularse por completo en el momento de la lectura, sin caché.'),
    ('Designing a news feed', 'Fan-out only refers to spreading traffic across multiple load balancers.', 'Fan-out solo se refiere a repartir el tráfico entre varios balanceadores de carga.'),
    ('Circuit breaker pattern', 'It stops a service from repeatedly calling a failing dependency by ''opening'' after a failure threshold, failing fast instead of piling up timeouts, and periodically testing if the dependency has recovered.', 'Evita que un servicio siga llamando repetidamente a una dependencia que falla, ''abriéndose'' tras superar un umbral de fallos, fallando rápido en lugar de acumular timeouts, y probando periódicamente si la dependencia se ha recuperado.'),
    ('Circuit breaker pattern', 'It physically disconnects a server''s network cable when it detects an attack.', 'Desconecta físicamente el cable de red de un servidor cuando detecta un ataque.'),
    ('Circuit breaker pattern', 'It''s a database transaction isolation level, not a resilience pattern.', 'Es un nivel de aislamiento de transacciones de base de datos, no un patrón de resiliencia.'),
    ('Data partitioning strategies', 'Range-based partitioning assigns contiguous key ranges to each partition (good for range queries, but risks hot spots); hash-based partitioning distributes keys more evenly via a hash function but makes range queries harder.', 'El particionado por rangos asigna rangos de claves contiguos a cada partición (bueno para consultas por rango, pero con riesgo de hot spots); el particionado por hash distribuye las claves de forma más uniforme mediante una función hash pero dificulta las consultas por rango.'),
    ('Data partitioning strategies', 'Range-based and hash-based partitioning always produce identical data distributions.', 'El particionado por rangos y por hash siempre producen distribuciones de datos idénticas.'),
    ('Data partitioning strategies', 'Partitioning strategy only affects storage cost, never query performance.', 'La estrategia de particionado solo afecta al coste de almacenamiento, nunca al rendimiento de las consultas.'),
    ('Distributed file storage', 'Splitting large files into chunks/blocks distributed and replicated across storage nodes, a metadata service mapping files to chunk locations, and mechanisms for consistency and re-replication when nodes fail.', 'Dividir los archivos grandes en fragmentos/bloques distribuidos y replicados entre nodos de almacenamiento, un servicio de metadatos que mapea los archivos a la ubicación de sus fragmentos, y mecanismos de consistencia y re-replicación cuando fallan nodos.'),
    ('Distributed file storage', 'Storing the entire file as a single unit on one server with no chunking.', 'Guardar el archivo entero como una sola unidad en un servidor, sin fragmentar.'),
    ('Distributed file storage', 'Distributed storage requires every client to keep a full local copy of all files.', 'El almacenamiento distribuido exige que cada cliente guarde una copia local completa de todos los archivos.'),
    ('CI/CD pipeline best practices', 'Automate build, tests and deploys on every change, keep pipelines fast, use immutable artifacts and have an automated rollback', 'Automatizar build, tests y despliegue en cada cambio, mantener los pipelines rápidos, usar artefactos inmutables y tener un rollback automatizado'),
    ('CI/CD pipeline best practices', 'Deploy manually from a developer laptop to keep control', 'Desplegar manualmente desde el portátil de un desarrollador para mantener el control'),
    ('CI/CD pipeline best practices', 'Run tests only after deploying to production', 'Ejecutar los tests solo después de desplegar a producción'),
    ('Blue-green vs canary deployments', 'Blue-green switches all traffic between two identical environments; canary gradually shifts a small percentage of traffic to the new version', 'Blue-green cambia todo el tráfico entre dos entornos idénticos; canary desplaza gradualmente un pequeño porcentaje de tráfico a la nueva versión'),
    ('Blue-green vs canary deployments', 'Canary releases replace all servers at once', 'Los despliegues canary reemplazan todos los servidores a la vez'),
    ('Blue-green vs canary deployments', 'Blue-green refers to the color theme of the monitoring dashboard', 'Blue-green se refiere al tema de color del panel de monitorización'),
    ('Infrastructure as Code (Terraform)', 'Defining infrastructure in versioned files; declarative tools like Terraform describe the desired state and compute the changes', 'Definir la infraestructura en archivos versionados; herramientas declarativas como Terraform describen el estado deseado y calculan los cambios necesarios'),
    ('Infrastructure as Code (Terraform)', 'Writing application code that runs on servers', 'Escribir código de aplicación que se ejecuta en servidores'),
    ('Infrastructure as Code (Terraform)', 'Documenting servers in a wiki page', 'Documentar los servidores en una página de wiki'),
    ('Kubernetes basics (Pod, Service, Deployment)', 'A Pod runs containers, a Deployment manages replicas and rollouts, a Service gives stable networking, and Ingress routes external HTTP', 'Un Pod ejecuta contenedores, un Deployment gestiona réplicas y despliegues progresivos, un Service ofrece red estable, e Ingress enruta el tráfico HTTP externo'),
    ('Kubernetes basics (Pod, Service, Deployment)', 'A Pod is a physical server and a Service is a Docker image', 'Un Pod es un servidor físico y un Service es una imagen Docker'),
    ('Kubernetes basics (Pod, Service, Deployment)', 'Deployments are only used to store secrets', 'Los Deployments solo se usan para guardar secretos'),
    ('Reverse proxy', 'A server that sits between clients and backend servers, forwarding requests to the right backend and commonly handling TLS termination, load balancing, caching, and compression.', 'Un servidor que se sitúa entre los clientes y los servidores backend, reenviando las peticiones al backend correcto y encargándose habitualmente de la terminación TLS, el balanceo de carga, la caché y la compresión.'),
    ('Reverse proxy', 'A proxy that only forwards outbound requests from internal servers to the internet.', 'Un proxy que solo reenvía peticiones salientes de servidores internos hacia internet.'),
    ('Reverse proxy', 'A reverse proxy is another name for a VPN.', 'Un proxy inverso es otro nombre para una VPN.'),
    ('Nginx vs Apache', 'Nginx uses an event-driven, asynchronous architecture that handles many concurrent connections efficiently with low memory use; Apache traditionally uses a process/thread-per-connection model, which can use more resources under high concurrency.', 'Nginx usa una arquitectura asíncrona basada en eventos que gestiona muchas conexiones concurrentes de forma eficiente con poco consumo de memoria; Apache usa tradicionalmente un modelo de proceso/hilo por conexión, que puede consumir más recursos con alta concurrencia.'),
    ('Nginx vs Apache', 'Apache and Nginx are functionally identical with no architectural differences.', 'Apache y Nginx son funcionalmente idénticos, sin diferencias de arquitectura.'),
    ('Nginx vs Apache', 'Nginx can only serve static files and cannot proxy dynamic requests.', 'Nginx solo puede servir archivos estáticos y no puede hacer proxy de peticiones dinámicas.'),
    ('Monitoring and observability', 'Logs (discrete event records), metrics (numeric time-series measurements), and traces (the path of a request through distributed services).', 'Los logs (registros de eventos individuales), las métricas (medidas numéricas en series temporales) y las trazas (el recorrido de una petición por servicios distribuidos).'),
    ('Monitoring and observability', 'Uptime, CPU usage, and disk space are the only three pillars.', 'Uptime, uso de CPU y espacio en disco son los únicos tres pilares.'),
    ('Monitoring and observability', 'Observability refers only to how visually appealing a monitoring dashboard is.', 'La observabilidad solo se refiere a lo visualmente atractivo que sea un panel de monitorización.'),
    ('Logging best practices', 'Use structured (e.g. JSON) logs with consistent fields, include correlation/request IDs, log at appropriate levels (info/warn/error), and avoid logging sensitive data like passwords or tokens.', 'Usar logs estructurados (p. ej. JSON) con campos consistentes, incluir IDs de correlación/petición, registrar en el nivel adecuado (info/warn/error), y evitar registrar datos sensibles como contraseñas o tokens.'),
    ('Logging best practices', 'Logging should always write directly to the console with no structure or levels.', 'El logging siempre debería escribir directamente a la consola, sin estructura ni niveles.'),
    ('Logging best practices', 'Production systems should disable logging entirely to save disk space.', 'Los sistemas de producción deberían desactivar el logging por completo para ahorrar espacio en disco.'),
    ('Secrets management', 'Git history is hard to fully purge and often shared broadly, so a leaked secret could remain accessible indefinitely; secrets should instead be injected via environment variables or a dedicated secrets manager (like Vault or AWS Secrets Manager).', 'El historial de Git es difícil de purgar por completo y suele compartirse ampliamente, así que un secreto filtrado podría quedar accesible indefinidamente; en su lugar, los secretos deberían inyectarse mediante variables de entorno o un gestor de secretos dedicado (como Vault o AWS Secrets Manager).'),
    ('Secrets management', 'Committing secrets to Git is safe as long as the repository is set to private.', 'Commitear secretos en Git es seguro mientras el repositorio sea privado.'),
    ('Secrets management', 'Git automatically encrypts any file matching a filename like .env.', 'Git cifra automáticamente cualquier archivo con un nombre como .env.'),
    ('Feature flags', 'A runtime toggle that turns a feature on or off (often per user segment) without a new deploy, allowing gradual rollouts, A/B testing, and instant rollback of a problematic feature.', 'Un interruptor en tiempo de ejecución que activa o desactiva una funcionalidad (a menudo por segmento de usuario) sin necesidad de un nuevo despliegue, permitiendo lanzamientos graduales, A/B testing y revertir al instante una funcionalidad problemática.'),
    ('Feature flags', 'A flag set at compile time that can never be changed after deployment.', 'Un flag que se fija en tiempo de compilación y que nunca se puede cambiar después del despliegue.'),
    ('Feature flags', 'Feature flags are only used to mark deprecated code for deletion.', 'Los feature flags solo se usan para marcar código obsoleto pendiente de eliminar.'),
    ('GitOps', 'Using a Git repository as the single source of truth for declarative infrastructure/application state, where an automated controller continuously reconciles the live environment to match what''s committed to Git.', 'Usar un repositorio Git como única fuente de verdad para el estado declarativo de la infraestructura/aplicación, donde un controlador automatizado reconcilia continuamente el entorno real con lo que hay commiteado en Git.'),
    ('GitOps', 'GitOps means every developer has direct SSH access to production servers.', 'GitOps significa que todo desarrollador tiene acceso SSH directo a los servidores de producción.'),
    ('GitOps', 'GitOps is a branching strategy unrelated to deployment or infrastructure.', 'GitOps es una estrategia de branching sin relación con el despliegue o la infraestructura.'),
    ('Immutable infrastructure', 'Instead of patching running servers in place, you build a new server/image with the change and replace the old one entirely — reducing configuration drift and making deployments more predictable and reversible.', 'En lugar de parchear los servidores en marcha, se construye un servidor/imagen nueva con el cambio y se sustituye por completo la anterior, reduciendo el configuration drift y haciendo los despliegues más predecibles y reversibles.'),
    ('Immutable infrastructure', 'It means production infrastructure can never be updated once it is created.', 'Significa que la infraestructura de producción nunca se puede actualizar una vez creada.'),
    ('Immutable infrastructure', 'It refers to infrastructure that has no version control at all.', 'Se refiere a infraestructura que no tiene ningún control de versiones.'),
    ('Horizontal pod autoscaling', 'It periodically checks a metric (commonly CPU or memory utilization, or a custom metric) against a target threshold and adjusts the number of pod replicas up or down to try to keep the metric near that target.', 'Comprueba periódicamente una métrica (habitualmente uso de CPU o memoria, o una métrica personalizada) frente a un umbral objetivo, y ajusta el número de réplicas de pods al alza o a la baja para intentar mantener la métrica cerca de ese objetivo.'),
    ('Horizontal pod autoscaling', 'It scales based purely on the time of day, with no metric involved.', 'Escala basándose únicamente en la hora del día, sin ninguna métrica de por medio.'),
    ('Horizontal pod autoscaling', 'It always scales to the maximum replica count immediately after any traffic increase.', 'Siempre escala al número máximo de réplicas inmediatamente después de cualquier aumento de tráfico.'),
    ('Liveness vs readiness probes', 'A liveness probe determines if a container is still running correctly (a failure triggers a restart); a readiness probe determines if it''s ready to receive traffic (a failure removes it from the service''s load balancing without restarting it).', 'Una liveness probe determina si un contenedor sigue funcionando correctamente (un fallo provoca un reinicio); una readiness probe determina si está listo para recibir tráfico (un fallo lo saca del balanceo del servicio sin reiniciarlo).'),
    ('Liveness vs readiness probes', 'They are identical checks with different names for compatibility reasons.', 'Son comprobaciones idénticas con nombres distintos por motivos de compatibilidad.'),
    ('Liveness vs readiness probes', 'A readiness probe restarts the container; a liveness probe removes it from traffic.', 'Una readiness probe reinicia el contenedor; una liveness probe lo saca del tráfico.'),
    ('Container registries', 'It stores and versions built container images (tagged, e.g. by commit SHA) so they can be pulled reliably by staging/production environments after being built once in CI.', 'Almacena y versiona las imágenes de contenedor ya construidas (etiquetadas, p. ej. por el SHA del commit) para que los entornos de staging/producción puedan descargarlas de forma fiable tras construirse una única vez en CI.'),
    ('Container registries', 'It''s a database that stores application user accounts.', 'Es una base de datos que almacena las cuentas de usuario de la aplicación.'),
    ('Container registries', 'It''s used only to store source code, not built artifacts.', 'Solo se usa para guardar código fuente, no artefactos ya construidos.'),
    ('Zero-downtime deployment', 'Run the new version alongside the old one (e.g. rolling update or blue-green) and only shift traffic once new instances pass health checks, draining connections from old instances gracefully instead of killing them abruptly.', 'Ejecutar la nueva versión junto a la antigua (p. ej. rolling update o blue-green) y desviar el tráfico solo cuando las nuevas instancias pasan los health checks, drenando las conexiones de las instancias antiguas de forma controlada en vez de matarlas de golpe.'),
    ('Zero-downtime deployment', 'Zero-downtime deployment requires stopping the old version before starting the new one.', 'El despliegue sin downtime requiere detener la versión antigua antes de arrancar la nueva.'),
    ('Zero-downtime deployment', 'It''s only achievable by scheduling deployments during a maintenance window.', 'Solo se puede conseguir programando los despliegues en una ventana de mantenimiento.'),
    ('Monitoring alerts', 'It''s actionable (someone can actually do something about it), tied to a meaningful threshold or symptom (not just any anomaly), and avoids flapping/false positives that lead to alert fatigue.', 'Es accionable (alguien puede realmente hacer algo al respecto), está ligada a un umbral o síntoma significativo (no a cualquier anomalía), y evita el flapping/falsos positivos que generan fatiga de alertas.'),
    ('Monitoring alerts', 'A good alert fires for every single metric fluctuation, however small.', 'Una buena alerta salta ante cualquier fluctuación de una métrica, por pequeña que sea.'),
    ('Monitoring alerts', 'Alerts should never include any context about what triggered them.', 'Las alertas nunca deberían incluir contexto sobre qué las disparó.'),
    ('Configuration management tools', 'They let you declaratively define and automatically enforce a server''s configuration (packages, files, services) across many machines, avoiding manual, inconsistent, hard-to-reproduce setup steps.', 'Permiten definir de forma declarativa y aplicar automáticamente la configuración de un servidor (paquetes, archivos, servicios) en muchas máquinas, evitando pasos de configuración manuales, inconsistentes y difíciles de reproducir.'),
    ('Configuration management tools', 'They are used exclusively to manage DNS records for a domain.', 'Se usan exclusivamente para gestionar los registros DNS de un dominio.'),
    ('Configuration management tools', 'They replace the need for any container technology like Docker.', 'Eliminan la necesidad de cualquier tecnología de contenedores como Docker.'),
    ('SLA, SLO, and SLI', 'An SLI is a measured indicator (e.g. request latency); an SLO is an internal target for that indicator (e.g. 99.9% of requests under 200ms); an SLA is an external, often contractual, commitment with consequences if unmet.', 'Un SLI es un indicador medido (p. ej. la latencia de las peticiones); un SLO es un objetivo interno para ese indicador (p. ej. el 99,9% de las peticiones en menos de 200ms); un SLA es un compromiso externo, a menudo contractual, con consecuencias si no se cumple.'),
    ('SLA, SLO, and SLI', 'They are three different names for the exact same concept.', 'Son tres nombres distintos para exactamente el mismo concepto.'),
    ('SLA, SLO, and SLI', 'An SLA is always stricter than the SLO it''s built from.', 'Un SLA siempre es más estricto que el SLO en el que se basa.'),
    ('Rollback strategies', 'Redeploying the previous known-good image/version (common in blue-green or with version-tagged artifacts), or using a platform''s built-in rollback command that shifts traffic back to the prior release.', 'Volver a desplegar la última imagen/versión que funcionaba bien (habitual en blue-green o con artefactos etiquetados por versión), o usar el comando de rollback integrado de la plataforma que devuelve el tráfico a la versión anterior.'),
    ('Rollback strategies', 'Rollbacks require manually rewriting the application code from scratch.', 'Los rollbacks exigen reescribir manualmente el código de la aplicación desde cero.'),
    ('Rollback strategies', 'Once deployed, a release can never be reverted, only fixed forward.', 'Una vez desplegada, una versión nunca se puede revertir, solo corregir hacia delante.'),
    ('OWASP Top 10', 'A list of the most critical web risks, such as broken access control, injection, cryptographic failures and misconfiguration', 'Una lista de los riesgos web más críticos, como el control de acceso roto, la inyección, los fallos criptográficos y la mala configuración'),
    ('OWASP Top 10', 'The 10 most popular JavaScript frameworks', 'Los 10 frameworks de JavaScript más populares'),
    ('OWASP Top 10', 'A performance benchmark for web servers', 'Un benchmark de rendimiento para servidores web'),
    ('JWT vs session cookies', 'Sessions store state on the server and are easy to revoke; JWTs are stateless and scale easily but are hard to revoke before expiry', 'Las sesiones guardan el estado en el servidor y son fáciles de revocar; los JWT son stateless y escalan fácilmente pero son difíciles de revocar antes de que expiren'),
    ('JWT vs session cookies', 'JWTs are always more secure than session cookies', 'Los JWT siempre son más seguros que las cookies de sesión'),
    ('JWT vs session cookies', 'Session cookies cannot be used with HTTPS', 'Las cookies de sesión no se pueden usar con HTTPS'),
    ('XSS prevention strategies', 'Rely on React escaping, avoid or sanitize dangerouslySetInnerHTML (e.g. DOMPurify) and add a Content Security Policy', 'Confiar en el escapado de React, evitar o sanear dangerouslySetInnerHTML (p. ej. con DOMPurify) y añadir una Content Security Policy'),
    ('XSS prevention strategies', 'React makes XSS impossible even with dangerouslySetInnerHTML', 'React hace imposible el XSS incluso con dangerouslySetInnerHTML'),
    ('XSS prevention strategies', 'Minifying the JavaScript bundle prevents XSS', 'Minificar el bundle de JavaScript previene el XSS'),
    ('CSRF protection', 'CSRF tricks a logged-in browser into sending unwanted requests; defend with SameSite cookies and anti-CSRF tokens', 'CSRF engaña a un navegador con sesión iniciada para que envíe peticiones no deseadas; se defiende con cookies SameSite y tokens anti-CSRF'),
    ('CSRF protection', 'CSRF is prevented by hashing passwords with bcrypt', 'CSRF se previene hasheando las contraseñas con bcrypt'),
    ('CSRF protection', 'CSRF only affects GET requests to static files', 'CSRF solo afecta a peticiones GET a archivos estáticos'),
    ('SQL Injection prevention', 'Use parameterized queries / prepared statements (never string-concatenate user input into SQL), and validate/escape input as defense in depth.', 'Usar consultas parametrizadas / prepared statements (nunca concatenar como string la entrada del usuario en el SQL), y validar/escapar la entrada como capa extra de defensa.'),
    ('SQL Injection prevention', 'SQL injection is prevented automatically by using an ORM, with no other precautions needed.', 'La inyección SQL se previene automáticamente usando un ORM, sin necesitar ninguna otra precaución.'),
    ('SQL Injection prevention', 'It''s enough to filter out only the word SELECT from user input.', 'Basta con filtrar solo la palabra SELECT de la entrada del usuario.'),
    ('Password hashing', 'bcrypt/argon2 are deliberately slow and configurable (via a work factor/cost parameter) and include salting by design, making brute-force and rainbow-table attacks far more expensive than with a fast general-purpose hash like SHA-256.', 'bcrypt/argon2 son deliberadamente lentos y configurables (mediante un parámetro de coste/work factor) e incluyen salting por diseño, haciendo mucho más costosos los ataques de fuerza bruta y rainbow tables que con un hash genérico rápido como SHA-256.'),
    ('Password hashing', 'SHA-256 is actually more secure than bcrypt for storing passwords.', 'SHA-256 es en realidad más seguro que bcrypt para almacenar contraseñas.'),
    ('Password hashing', 'Password hashing algorithm choice has no effect on brute-force resistance.', 'La elección del algoritmo de hashing no afecta en nada a la resistencia frente a la fuerza bruta.'),
    ('HTTPS and TLS basics', 'Encryption of data in transit (confidentiality), integrity checking (tampering detection), and authentication of the server via its certificate.', 'Cifrado de los datos en tránsito (confidencialidad), comprobación de integridad (detección de manipulación), y autenticación del servidor mediante su certificado.'),
    ('HTTPS and TLS basics', 'TLS only encrypts the request headers, never the body of the request.', 'TLS solo cifra las cabeceras de la petición, nunca el cuerpo.'),
    ('HTTPS and TLS basics', 'HTTPS guarantees the application code itself has no vulnerabilities.', 'HTTPS garantiza que el propio código de la aplicación no tiene vulnerabilidades.'),
    ('CORS explained', 'Cross-Origin Resource Sharing is a browser mechanism that lets a server explicitly allow (via headers like Access-Control-Allow-Origin) web pages from other origins to make requests to it, relaxing the default same-origin restriction safely.', 'Cross-Origin Resource Sharing es un mecanismo del navegador que permite a un servidor autorizar explícitamente (mediante cabeceras como Access-Control-Allow-Origin) que páginas de otros orígenes le hagan peticiones, relajando de forma segura la restricción same-origin por defecto.'),
    ('CORS explained', 'CORS is a server-side firewall that blocks all cross-origin requests permanently.', 'CORS es un firewall del lado servidor que bloquea permanentemente todas las peticiones cross-origin.'),
    ('CORS explained', 'CORS encrypts requests made between different domains.', 'CORS cifra las peticiones hechas entre distintos dominios.'),
    ('Rate limiting for security', 'By capping the number of login attempts allowed from a given account/IP within a time window, it makes it impractical for an attacker to try large numbers of password guesses quickly.', 'Al limitar el número de intentos de login permitidos desde una cuenta/IP en una ventana de tiempo, hace inviable que un atacante pruebe rápidamente un gran número de contraseñas.'),
    ('Rate limiting for security', 'Rate limiting only protects against SQL injection, not brute-force attacks.', 'El rate limiting solo protege contra la inyección SQL, no contra los ataques de fuerza bruta.'),
    ('Rate limiting for security', 'Rate limiting is applied exclusively to outbound requests from the server.', 'El rate limiting solo se aplica a las peticiones salientes del servidor.'),
    ('Principle of least privilege', 'Every user, process, or service should be granted only the minimum permissions necessary to do its job, limiting the damage possible if that account or component is compromised.', 'A cada usuario, proceso o servicio se le deberían conceder solo los permisos mínimos necesarios para hacer su trabajo, limitando el daño posible si esa cuenta o componente se ve comprometido.'),
    ('Principle of least privilege', 'Every account should be granted admin access by default for convenience.', 'A toda cuenta se le debería dar acceso de administrador por defecto, por comodidad.'),
    ('Principle of least privilege', 'It applies only to database users, not application services or employees.', 'Solo se aplica a los usuarios de base de datos, no a los servicios de la aplicación ni a los empleados.'),
    ('Secure cookie flags', 'HttpOnly blocks JavaScript from reading the cookie (mitigating XSS token theft); Secure ensures the cookie is only sent over HTTPS; SameSite restricts when the cookie is sent on cross-site requests (mitigating CSRF).', 'HttpOnly impide que JavaScript pueda leer la cookie (mitigando el robo de tokens por XSS); Secure garantiza que la cookie solo se envíe por HTTPS; SameSite restringe cuándo se envía la cookie en peticiones cross-site (mitigando CSRF).'),
    ('Secure cookie flags', 'All three flags do the exact same thing: encrypt the cookie''s value.', 'Los tres flags hacen exactamente lo mismo: cifrar el valor de la cookie.'),
    ('Secure cookie flags', 'These flags are only relevant for cookies set by third-party ad networks.', 'Estos flags solo son relevantes para cookies puestas por redes publicitarias de terceros.'),
    ('Content Security Policy', 'It restricts which sources (scripts, styles, images, etc.) a page is allowed to load content from, significantly reducing the impact of XSS by blocking execution of injected, disallowed scripts.', 'Restringe desde qué orígenes (scripts, estilos, imágenes, etc.) se le permite a una página cargar contenido, reduciendo significativamente el impacto de XSS al bloquear la ejecución de scripts inyectados no permitidos.'),
    ('Content Security Policy', 'CSP encrypts all content on the page so it cannot be viewed by attackers.', 'CSP cifra todo el contenido de la página para que los atacantes no puedan verlo.'),
    ('Content Security Policy', 'CSP is a database-level access control policy, unrelated to the browser.', 'CSP es una política de control de acceso a nivel de base de datos, sin relación con el navegador.'),
    ('Dependency vulnerability scanning', 'To detect known vulnerabilities in third-party dependencies (and their transitive dependencies) early, since a vulnerable library can be exploited even if your own code has no bugs.', 'Para detectar pronto vulnerabilidades conocidas en dependencias de terceros (y sus dependencias transitivas), ya que una librería vulnerable se puede explotar aunque tu propio código no tenga fallos.'),
    ('Dependency vulnerability scanning', 'These tools are only used to check code style, not security.', 'Estas herramientas solo se usan para comprobar el estilo del código, no la seguridad.'),
    ('Dependency vulnerability scanning', 'Dependency scanning replaces the need for any other security testing.', 'El escaneo de dependencias elimina la necesidad de cualquier otro testing de seguridad.'),
    ('Two-factor authentication', 'A second, independent proof of identity (something you have, like a one-time code from an app or SMS, or something you are, like a fingerprint), so a leaked password alone isn''t enough to log in.', 'Una segunda prueba de identidad independiente (algo que tienes, como un código de un solo uso de una app o SMS, o algo que eres, como una huella dactilar), de forma que una contraseña filtrada por sí sola no baste para iniciar sesión.'),
    ('Two-factor authentication', 'It requires the user to enter their password twice for confirmation.', 'Exige que el usuario introduzca su contraseña dos veces para confirmarla.'),
    ('Two-factor authentication', 'It replaces passwords entirely with a single security question.', 'Sustituye por completo las contraseñas por una única pregunta de seguridad.'),
    ('OAuth 2.0 flow', 'It lets a user grant a third-party application limited access to their resources on another service (e.g. ''Sign in with Google'') without sharing their actual password with that third-party application.', 'Permite que un usuario conceda a una aplicación de terceros acceso limitado a sus recursos en otro servicio (p. ej. ''Iniciar sesión con Google'') sin compartir su contraseña real con esa aplicación de terceros.'),
    ('OAuth 2.0 flow', 'OAuth 2.0 is a way to encrypt passwords before storing them in a database.', 'OAuth 2.0 es una forma de cifrar contraseñas antes de guardarlas en una base de datos.'),
    ('OAuth 2.0 flow', 'OAuth 2.0 is only used for encrypting HTTP traffic, replacing TLS.', 'OAuth 2.0 solo se usa para cifrar el tráfico HTTP, sustituyendo a TLS.'),
    ('Clickjacking prevention', 'Send an X-Frame-Options header (or the frame-ancestors directive in CSP) to prevent the page from being embedded in a hidden iframe on an attacker''s site that tricks users into clicking disguised elements.', 'Enviando una cabecera X-Frame-Options (o la directiva frame-ancestors de CSP) para evitar que la página se pueda incrustar en un iframe oculto en el sitio de un atacante, que engaña a los usuarios para que hagan clic en elementos disfrazados.'),
    ('Clickjacking prevention', 'Clickjacking is prevented automatically by using HTTPS.', 'El clickjacking se previene automáticamente usando HTTPS.'),
    ('Clickjacking prevention', 'Clickjacking can only be prevented by disabling JavaScript on the page.', 'El clickjacking solo se puede prevenir desactivando JavaScript en la página.'),
    ('Secrets in env vars vs a vault', 'Plain env vars typically lack built-in rotation, fine-grained access auditing, and can be exposed via process listings, crash dumps, or logs, whereas a secrets manager offers rotation, access control, and audit trails.', 'Las variables de entorno planas normalmente no tienen rotación integrada ni auditoría de acceso fina, y pueden quedar expuestas en listados de procesos, volcados de errores o logs, mientras que un gestor de secretos ofrece rotación, control de acceso y registro de auditoría.'),
    ('Secrets in env vars vs a vault', 'Environment variables are always more secure than a secrets manager.', 'Las variables de entorno siempre son más seguras que un gestor de secretos.'),
    ('Secrets in env vars vs a vault', 'There is no meaningful difference between the two approaches.', 'No hay ninguna diferencia relevante entre los dos enfoques.'),
    ('Input validation and sanitization', 'Validation checks that input conforms to expected rules (type, length, format) and rejects it if not; sanitization modifies/cleans input (e.g. stripping HTML tags) to make it safe to use even if imperfect.', 'La validación comprueba que la entrada cumple unas reglas esperadas (tipo, longitud, formato) y la rechaza si no; el saneamiento modifica/limpia la entrada (p. ej. eliminando etiquetas HTML) para que se pueda usar de forma segura aunque no sea perfecta.'),
    ('Input validation and sanitization', 'Validation and sanitization are two names for the exact same operation.', 'Validación y saneamiento son dos nombres para exactamente la misma operación.'),
    ('Input validation and sanitization', 'Only one of the two is ever necessary; using both is redundant.', 'Solo hace falta uno de los dos; usar ambos es redundante.'),
    ('SSRF', 'It occurs when an attacker tricks a server into making unintended requests (e.g. to internal-only services or cloud metadata endpoints) by manipulating a URL the server fetches on the attacker''s behalf.', 'Ocurre cuando un atacante engaña a un servidor para que haga peticiones no previstas (p. ej. a servicios internos o a endpoints de metadatos de la nube) manipulando una URL que el servidor obtiene en nombre del atacante.'),
    ('SSRF', 'It''s a client-side attack where a script forges requests from the victim''s browser.', 'Es un ataque del lado cliente en el que un script falsifica peticiones desde el navegador de la víctima.'),
    ('SSRF', 'SSRF refers to forging the Referer header to bypass CSRF protection.', 'SSRF se refiere a falsificar la cabecera Referer para saltarse la protección CSRF.'),
    ('Security headers (helmet.js)', 'It sets a collection of security-related HTTP response headers (like CSP, X-Frame-Options, X-Content-Type-Options) with sensible defaults, reducing exposure to several common web vulnerabilities.', 'Configura un conjunto de cabeceras de respuesta HTTP relacionadas con la seguridad (como CSP, X-Frame-Options, X-Content-Type-Options) con valores por defecto sensatos, reduciendo la exposición a varias vulnerabilidades web comunes.'),
    ('Security headers (helmet.js)', 'It encrypts the entire HTTP request and response bodies automatically.', 'Cifra automáticamente todo el cuerpo de las peticiones y respuestas HTTP.'),
    ('Security headers (helmet.js)', 'It replaces the need for authentication middleware entirely.', 'Elimina por completo la necesidad de un middleware de autenticación.'),
    ('Unit vs integration vs E2E tests', 'Many fast unit tests at the base, fewer integration tests, and a few slow E2E tests at the top of the pyramid', 'Muchos tests unitarios rápidos en la base, menos tests de integración, y unos pocos tests E2E lentos en la cima de la pirámide'),
    ('Unit vs integration vs E2E tests', 'Mostly E2E tests with very few unit tests', 'Sobre todo tests E2E con muy pocos tests unitarios'),
    ('Unit vs integration vs E2E tests', 'Integration tests replace the need for any other test', 'Los tests de integración eliminan la necesidad de cualquier otro test'),
    ('Mocking strategies in tests', 'Stubs return canned data, spies record calls on real functions, and mocks verify expected interactions', 'Los stubs devuelven datos predefinidos, los spies registran las llamadas a funciones reales, y los mocks verifican las interacciones esperadas'),
    ('Mocking strategies in tests', 'Stubs, mocks and spies are all the same thing', 'Stubs, mocks y spies son todos lo mismo'),
    ('Mocking strategies in tests', 'Mocks are only used in production code', 'Los mocks solo se usan en código de producción'),
    ('TDD vs BDD', 'TDD writes a failing test first then the code (red-green-refactor); BDD describes behavior in business language (Given/When/Then)', 'TDD escribe primero un test que falla y luego el código (red-green-refactor); BDD describe el comportamiento en lenguaje de negocio (Given/When/Then)'),
    ('TDD vs BDD', 'BDD means writing tests after the code is released', 'BDD significa escribir los tests después de publicar el código'),
    ('TDD vs BDD', 'TDD is only for frontend and BDD only for backend', 'TDD es solo para frontend y BDD solo para backend'),
    ('Testing async code', 'Await promises in tests, use fake timers for setTimeout, and mock external APIs to keep tests deterministic', 'Esperar (await) las promises en los tests, usar temporizadores falsos para setTimeout, y mockear las APIs externas para que los tests sean deterministas'),
    ('Testing async code', 'Add long sleeps so the async work has time to finish', 'Añadir esperas largas para que el trabajo asíncrono tenga tiempo de terminar'),
    ('Testing async code', 'Async code cannot be tested automatically', 'El código asíncrono no se puede testear de forma automática'),
    ('Code coverage metrics', 'It measures how much of the code was executed by the test suite (e.g. line or branch coverage); it does NOT guarantee the tests actually assert correct behavior — code can be ''covered'' but not meaningfully tested.', 'Mide qué parte del código ejecutó la suite de tests (p. ej. cobertura de líneas o de ramas); NO garantiza que los tests comprueben realmente el comportamiento correcto: código puede estar ''cubierto'' sin estar realmente bien testeado.'),
    ('Code coverage metrics', '100% code coverage guarantees the application has zero bugs.', 'Un 100% de cobertura de código garantiza que la aplicación no tiene ningún bug.'),
    ('Code coverage metrics', 'Code coverage measures how fast the test suite runs.', 'La cobertura de código mide lo rápido que se ejecuta la suite de tests.'),
    ('Snapshot testing', 'It captures a serialized output (e.g. rendered component markup) and compares future runs against the stored snapshot; a common pitfall is developers blindly approving/updating snapshots without reviewing whether the change is actually correct.', 'Captura una salida serializada (p. ej. el markup renderizado de un componente) y compara ejecuciones futuras contra el snapshot guardado; un error común es que los desarrolladores aprueben/actualicen snapshots a ciegas sin revisar si el cambio es realmente correcto.'),
    ('Snapshot testing', 'Snapshot testing only works for testing database schemas.', 'El snapshot testing solo sirve para testear esquemas de base de datos.'),
    ('Snapshot testing', 'Snapshots are regenerated automatically and never need developer review.', 'Los snapshots se regeneran automáticamente y nunca necesitan revisión del desarrollador.'),
    ('Fakes, stubs, and mocks', 'A fake is a working, simplified implementation (like an in-memory DB); a stub returns canned responses to calls; a mock additionally verifies that specific interactions (calls, arguments) actually happened.', 'Un fake es una implementación funcional y simplificada (como una BD en memoria); un stub devuelve respuestas predefinidas a las llamadas; un mock además verifica que ciertas interacciones concretas (llamadas, argumentos) realmente ocurrieron.'),
    ('Fakes, stubs, and mocks', 'They are interchangeable terms for the exact same testing concept.', 'Son términos intercambiables para exactamente el mismo concepto de testing.'),
    ('Fakes, stubs, and mocks', 'A mock is a simplified working implementation, and a fake verifies interactions.', 'Un mock es una implementación funcional simplificada, y un fake verifica interacciones.'),
    ('Arrange-Act-Assert', 'A way to structure a test into three clear sections: set up the test''s preconditions (Arrange), perform the action under test (Act), and verify the outcome (Assert).', 'Una forma de estructurar un test en tres secciones claras: preparar las condiciones previas del test (Arrange), ejecutar la acción que se está probando (Act), y verificar el resultado (Assert).'),
    ('Arrange-Act-Assert', 'It''s a pattern for arranging test files alphabetically in a directory.', 'Es un patrón para ordenar alfabéticamente los archivos de test en un directorio.'),
    ('Arrange-Act-Assert', 'It requires running the Assert step before the Act step for validation.', 'Exige ejecutar el paso Assert antes que el paso Act para validar.'),
    ('Flaky tests', 'Shared mutable state between tests, race conditions in async code, reliance on real time/network calls, or test order dependence — all sources of non-determinism the test doesn''t properly control.', 'Estado mutable compartido entre tests, condiciones de carrera en código asíncrono, depender de tiempo real/llamadas de red, o depender del orden de ejecución: todas fuentes de no-determinismo que el test no controla bien.'),
    ('Flaky tests', 'Flaky tests are always caused by a bug in the testing framework itself.', 'Los tests flaky siempre los causa un fallo del propio framework de testing.'),
    ('Flaky tests', 'Flakiness only occurs in end-to-end tests, never in unit tests.', 'La inestabilidad solo ocurre en tests end-to-end, nunca en los unitarios.'),
    ('Testing pyramid vs trophy', 'The pyramid emphasizes mostly unit tests with few E2E tests; the trophy (popularized for frontend testing) puts more relative weight on integration tests, arguing they give better confidence per unit of effort for many UI-heavy applications.', 'La pirámide da prioridad sobre todo a los tests unitarios con pocos E2E; el trofeo (popularizado para el testing de frontend) le da más peso relativo a los tests de integración, argumentando que dan más confianza por unidad de esfuerzo en muchas aplicaciones con mucha UI.'),
    ('Testing pyramid vs trophy', 'The testing trophy removes unit tests entirely in favor of only E2E tests.', 'El trofeo de testing elimina por completo los tests unitarios a favor de solo tests E2E.'),
    ('Testing pyramid vs trophy', 'They describe the exact same test distribution with different shape names.', 'Describen exactamente la misma distribución de tests con nombres de forma distintos.'),
    ('Contract testing', 'It verifies that a service''s API still matches the expectations (the ''contract'') its consumers rely on, catching breaking changes early without needing full end-to-end integration tests across every service.', 'Verifica que la API de un servicio sigue cumpliendo las expectativas (el ''contrato'') de las que dependen sus consumidores, detectando cambios que rompen algo de forma temprana sin necesitar tests de integración end-to-end completos entre todos los servicios.'),
    ('Contract testing', 'Contract testing is a legal review process for open-source license compliance.', 'El contract testing es un proceso de revisión legal para cumplir licencias open-source.'),
    ('Contract testing', 'It only tests that HTTP status codes are returned, ignoring payload shape.', 'Solo comprueba que se devuelven los códigos de estado HTTP, ignorando la forma del payload.'),
    ('Load testing', 'How the system behaves under expected or peak traffic — throughput, response times, and where bottlenecks or failures start to appear as load increases.', 'Cómo se comporta el sistema con tráfico esperado o de pico: el throughput, los tiempos de respuesta, y dónde empiezan a aparecer cuellos de botella o fallos al aumentar la carga.'),
    ('Load testing', 'It tests whether the UI text fits correctly on different screen sizes.', 'Comprueba si el texto de la UI encaja correctamente en distintos tamaños de pantalla.'),
    ('Load testing', 'Load testing is a synonym for unit testing run in a CI pipeline.', 'El load testing es un sinónimo de los tests unitarios ejecutados en un pipeline de CI.'),
    ('TDD red-green-refactor', 'Red: write a failing test for behavior that doesn''t exist yet. Green: write the minimal code to make it pass. Refactor: clean up the code while keeping the test passing.', 'Rojo: escribir un test que falla para un comportamiento que aún no existe. Verde: escribir el código mínimo para que pase. Refactor: limpiar el código manteniendo el test en verde.'),
    ('TDD red-green-refactor', 'Red: fix a bug. Green: deploy to production. Refactor: write documentation.', 'Rojo: arreglar un bug. Verde: desplegar a producción. Refactor: escribir documentación.'),
    ('TDD red-green-refactor', 'The cycle has no fixed order and steps can be done in any sequence.', 'El ciclo no tiene un orden fijo y los pasos se pueden hacer en cualquier secuencia.'),
    ('Mutation testing', 'It deliberately introduces small bugs (''mutants'') into the code and checks whether the test suite catches them (kills the mutant) — measuring whether tests actually assert meaningful behavior, not just execute lines.', 'Introduce deliberadamente pequeños fallos (''mutantes'') en el código y comprueba si la suite de tests los detecta (mata al mutante), midiendo si los tests realmente verifican un comportamiento significativo y no solo ejecutan líneas.'),
    ('Mutation testing', 'It measures how many times a test suite mutates shared global state.', 'Mide cuántas veces una suite de tests muta el estado global compartido.'),
    ('Mutation testing', 'Mutation testing only checks for typos in test file names.', 'El mutation testing solo comprueba erratas en los nombres de los archivos de test.'),
    ('Continuous testing in CI', 'To catch regressions before they''re merged, giving fast feedback to the author and preventing broken code from reaching the main branch or production.', 'Para detectar regresiones antes de fusionarlas, dando feedback rápido al autor y evitando que código roto llegue a la rama principal o a producción.'),
    ('Continuous testing in CI', 'CI testing is only useful for catching formatting/linting issues.', 'El testing en CI solo sirve para detectar problemas de formato/linting.'),
    ('Continuous testing in CI', 'Running tests in CI removes the need to ever run them locally.', 'Ejecutar los tests en CI elimina la necesidad de ejecutarlos nunca en local.'),
    ('Property-based testing', 'Instead of asserting behavior for a handful of hand-picked inputs, it defines a general property that should hold (e.g. ''reversing a list twice returns the original'') and lets the framework generate many varied, often edge-case, inputs to check it.', 'En lugar de comprobar el comportamiento para un puñado de entradas elegidas a mano, define una propiedad general que debe cumplirse (p. ej. ''invertir una lista dos veces devuelve la original'') y deja que el framework genere muchas entradas variadas, a menudo casos límite, para comprobarla.'),
    ('Property-based testing', 'Property-based testing only works on functions that return booleans.', 'El property-based testing solo funciona con funciones que devuelven booleanos.'),
    ('Property-based testing', 'It replaces the need to write any assertions at all.', 'Elimina por completo la necesidad de escribir ninguna aserción.'),
    ('Testing React components', 'Testing components the way a user would interact with them (querying by visible text/role, simulating clicks/typing) rather than asserting on internal implementation details like state or private methods.', 'Testear los componentes tal como interactuaría con ellos un usuario (consultando por texto/rol visible, simulando clics/escritura) en lugar de comprobar detalles internos de implementación como el estado o métodos privados.'),
    ('Testing React components', 'It encourages testing private component internals and state directly.', 'Fomenta testear directamente los internos privados y el estado de los componentes.'),
    ('Testing React components', 'It requires a real browser and cannot run in a headless test environment.', 'Requiere un navegador real y no puede ejecutarse en un entorno de test headless.'),
    ('Visual regression testing', 'Unintended visual/styling changes (layout shifts, broken CSS, wrong colors) by comparing screenshots against a baseline, even when the underlying logic and DOM structure are functionally correct.', 'Cambios visuales/de estilo no deseados (desplazamientos de layout, CSS roto, colores incorrectos) comparando capturas de pantalla contra una base de referencia, incluso cuando la lógica y la estructura del DOM son funcionalmente correctas.'),
    ('Visual regression testing', 'It only checks that JavaScript errors don''t appear in the console.', 'Solo comprueba que no aparezcan errores de JavaScript en la consola.'),
    ('Visual regression testing', 'Visual regression testing replaces the need for any functional testing.', 'El testing de regresión visual elimina la necesidad de cualquier testing funcional.'),
    ('Smoke testing', 'A quick set of tests covering the most critical, high-level functionality (does the app start, can a user log in) run after a deploy to catch major breakage before running a fuller test suite.', 'Un conjunto rápido de tests que cubre la funcionalidad de más alto nivel y crítica (¿arranca la app?, ¿puede un usuario iniciar sesión?), ejecutado tras un despliegue para detectar roturas importantes antes de lanzar una suite de tests más completa.'),
    ('Smoke testing', 'A smoke test is a stress test that pushes the system to its breaking point.', 'Un smoke test es una prueba de estrés que lleva al sistema hasta su punto de ruptura.'),
    ('Smoke testing', 'Smoke tests are only run once a year during a full security audit.', 'Los smoke tests solo se ejecutan una vez al año durante una auditoría de seguridad completa.'),
    ('Test isolation', 'Isolated tests can run in any order or in parallel, fail with a clear cause, and won''t produce false passes/failures from leftover state set up by a previous test.', 'Los tests aislados se pueden ejecutar en cualquier orden o en paralelo, fallan con una causa clara, y no producen falsos positivos/negativos por estado residual dejado por un test anterior.'),
    ('Test isolation', 'Test isolation means tests must always run one at a time on a single core.', 'El aislamiento de tests significa que siempre deben ejecutarse de uno en uno en un solo núcleo.'),
    ('Test isolation', 'Isolation is only relevant for end-to-end tests, not unit tests.', 'El aislamiento solo es relevante para los tests end-to-end, no para los unitarios.'),
    ('Core Web Vitals', 'LCP measures loading, INP measures responsiveness and CLS measures visual stability; measured with Lighthouse and field data', 'LCP mide la carga, INP mide la capacidad de respuesta y CLS mide la estabilidad visual; se miden con Lighthouse y con datos de campo'),
    ('Core Web Vitals', 'They measure the number of lines of code in the bundle', 'Miden el número de líneas de código del bundle'),
    ('Core Web Vitals', 'They are server CPU and memory metrics', 'Son métricas de CPU y memoria del servidor'),
    ('Code splitting and lazy loading', 'Split the bundle with dynamic import() and React.lazy so code is loaded only when needed, reducing initial load', 'Dividir el bundle con import() dinámico y React.lazy para que el código se cargue solo cuando hace falta, reduciendo la carga inicial'),
    ('Code splitting and lazy loading', 'Merge all code into one file so the browser makes a single request', 'Fusionar todo el código en un único archivo para que el navegador haga una sola petición'),
    ('Code splitting and lazy loading', 'Delay the execution of every function by a few seconds', 'Retrasar unos segundos la ejecución de cada función'),
    ('Critical rendering path', 'The steps from HTML/CSS/JS to pixels (DOM, CSSOM, render tree, layout, paint); optimize by reducing render-blocking resources', 'Los pasos desde HTML/CSS/JS hasta los píxeles (DOM, CSSOM, render tree, layout, paint); se optimiza reduciendo los recursos que bloquean el renderizado'),
    ('Critical rendering path', 'The path of the API requests made after the page has loaded', 'El recorrido de las peticiones a la API que se hacen después de cargar la página'),
    ('Critical rendering path', 'The order in which images are compressed on the server', 'El orden en el que se comprimen las imágenes en el servidor'),
    ('Tree shaking and bundle analysis', 'Removing unused ES module exports at build time; analyze the bundle with tools like rollup-plugin-visualizer or webpack-bundle-analyzer', 'Eliminar en tiempo de build los exports de módulos ES que no se usan; el bundle se analiza con herramientas como rollup-plugin-visualizer o webpack-bundle-analyzer'),
    ('Tree shaking and bundle analysis', 'Deleting unused files from the node_modules folder by hand', 'Borrar a mano los archivos que no se usan de la carpeta node_modules'),
    ('Tree shaking and bundle analysis', 'Minifying CSS class names', 'Minificar los nombres de las clases CSS'),
    ('Lazy loading images', 'Images outside the initial viewport (e.g. via loading="lazy" or an IntersectionObserver) are only fetched as the user scrolls near them, reducing initial page weight and speeding up first load.', 'Las imágenes fuera del viewport inicial (p. ej. mediante loading="lazy" o un IntersectionObserver) solo se cargan cuando el usuario hace scroll cerca de ellas, reduciendo el peso inicial de la página y acelerando la primera carga.'),
    ('Lazy loading images', 'Lazy loading compresses every image on the page before it is ever requested.', 'El lazy loading comprime todas las imágenes de la página antes de que se lleguen a pedir.'),
    ('Lazy loading images', 'It loads all images in parallel immediately, just in a randomized order.', 'Carga todas las imágenes en paralelo de inmediato, solo que en un orden aleatorio.'),
    ('Caching headers', 'Cache-Control specifies how long and under what conditions a response can be cached (by the browser or a CDN); ETag provides a version identifier the client can send back to let the server confirm a cached copy is still valid (returning 304 Not Modified) instead of resending the full response.', 'Cache-Control especifica cuánto tiempo y bajo qué condiciones se puede cachear una respuesta (por el navegador o un CDN); ETag ofrece un identificador de versión que el cliente puede devolver para que el servidor confirme que la copia cacheada sigue siendo válida (devolviendo 304 Not Modified) en vez de reenviar la respuesta completa.'),
    ('Caching headers', 'They control how images are compressed before being sent to the client.', 'Controlan cómo se comprimen las imágenes antes de enviarse al cliente.'),
    ('Caching headers', 'ETag encrypts the response body, Cache-Control encrypts the headers.', 'ETag cifra el cuerpo de la respuesta, Cache-Control cifra las cabeceras.'),
    ('Compression (gzip/brotli)', 'It reduces the number of bytes transferred over the network for text-based assets (HTML, CSS, JS, JSON), which speeds up download time especially on slower connections, at the cost of some CPU to compress/decompress.', 'Reduce el número de bytes transferidos por la red para assets de texto (HTML, CSS, JS, JSON), lo que acelera la descarga, especialmente en conexiones lentas, a costa de algo de CPU para comprimir/descomprimir.'),
    ('Compression (gzip/brotli)', 'Compression reduces the number of HTTP requests a page makes.', 'La compresión reduce el número de peticiones HTTP que hace una página.'),
    ('Compression (gzip/brotli)', 'gzip and brotli only work on image files, not text-based assets.', 'gzip y brotli solo funcionan con archivos de imagen, no con assets de texto.'),
    ('Preload vs prefetch', 'preload tells the browser to fetch a resource needed for the CURRENT page with high priority as soon as possible; prefetch fetches a resource likely needed for a FUTURE navigation, at low priority during idle time.', 'preload le indica al navegador que cargue con prioridad alta y cuanto antes un recurso que hace falta en la página ACTUAL; prefetch carga con prioridad baja, en tiempos muertos, un recurso que probablemente se necesitará en una navegación FUTURA.'),
    ('Preload vs prefetch', 'They are identical hints; the names are just aliases for the same behavior.', 'Son pistas idénticas; los nombres son solo alias del mismo comportamiento.'),
    ('Preload vs prefetch', 'prefetch is for the current page and preload is for future navigations.', 'prefetch es para la página actual y preload es para navegaciones futuras.'),
    ('Image formats', 'They typically achieve significantly smaller file sizes at comparable visual quality through more efficient compression, reducing page weight and load time.', 'Normalmente logran tamaños de archivo bastante más pequeños con una calidad visual comparable gracias a una compresión más eficiente, reduciendo el peso de la página y el tiempo de carga.'),
    ('Image formats', 'WebP and AVIF always look worse than JPEG regardless of file size.', 'WebP y AVIF siempre se ven peor que JPEG sin importar el tamaño del archivo.'),
    ('Image formats', 'Modern image formats can only be used for icons, never photographs.', 'Los formatos de imagen modernos solo se pueden usar para iconos, nunca para fotografías.'),
    ('Debouncing scroll/resize handlers', 'These events can fire dozens of times per second; running expensive work (like layout calculations) on every single event can jank the UI, so limiting how often the handler actually runs keeps things smooth.', 'Estos eventos pueden dispararse decenas de veces por segundo; ejecutar trabajo costoso (como cálculos de layout) en cada evento puede provocar tirones en la UI, así que limitar la frecuencia con la que se ejecuta el handler mantiene todo fluido.'),
    ('Debouncing scroll/resize handlers', 'Debouncing these handlers is purely a code-style preference with no performance effect.', 'Aplicar debounce a estos handlers es solo una preferencia de estilo de código sin efecto en el rendimiento.'),
    ('Debouncing scroll/resize handlers', 'Scroll and resize events only fire once per page, so throttling has no effect.', 'Los eventos de scroll y resize solo se disparan una vez por página, así que el throttle no tiene ningún efecto.'),
    ('List virtualization', 'Rendering thousands of DOM nodes for a huge list is slow and memory-intensive; virtualization renders only the rows currently visible in the viewport (plus a small buffer), dramatically improving render and scroll performance.', 'Renderizar miles de nodos del DOM para una lista enorme es lento y consume mucha memoria; la virtualización solo renderiza las filas visibles en el viewport (más un pequeño margen), mejorando muchísimo el rendimiento del renderizado y del scroll.'),
    ('List virtualization', 'Virtualization pre-renders the entire list off-screen ahead of time.', 'La virtualización pre-renderiza toda la lista fuera de pantalla por adelantado.'),
    ('List virtualization', 'It only applies to images, not text-based list rows.', 'Solo se aplica a imágenes, no a filas de lista con texto.'),
    ('Minification and bundling', 'Minification strips whitespace/comments and shortens identifiers to reduce file size; bundling combines many modules into fewer files, reducing the number of separate network requests the browser must make.', 'La minificación elimina espacios en blanco/comentarios y acorta identificadores para reducir el tamaño del archivo; el bundling combina muchos módulos en menos archivos, reduciendo el número de peticiones de red distintas que debe hacer el navegador.'),
    ('Minification and bundling', 'Minification and bundling both work exclusively on image assets.', 'La minificación y el bundling solo funcionan con assets de imagen.'),
    ('Minification and bundling', 'Bundling always increases the number of requests, which is the trade-off for minification.', 'El bundling siempre aumenta el número de peticiones, lo cual es la contrapartida de la minificación.'),
    ('HTTP/2 multiplexing', 'It allows many requests and responses to be interleaved over a single TCP connection concurrently, avoiding the head-of-line blocking and per-domain connection limits that made HTTP/1.1 rely on techniques like domain sharding.', 'Permite que muchas peticiones y respuestas se entrelacen simultáneamente sobre una única conexión TCP, evitando el head-of-line blocking y los límites de conexiones por dominio que obligaban a HTTP/1.1 a recurrir a técnicas como el domain sharding.'),
    ('HTTP/2 multiplexing', 'Multiplexing means every request opens its own dedicated TCP connection, like HTTP/1.1.', 'El multiplexado significa que cada petición abre su propia conexión TCP dedicada, como en HTTP/1.1.'),
    ('HTTP/2 multiplexing', 'HTTP/2 multiplexing only applies to image requests, not scripts or stylesheets.', 'El multiplexado de HTTP/2 solo se aplica a peticiones de imágenes, no a scripts u hojas de estilo.'),
    ('Service workers and caching', 'It runs as a network proxy in the browser, letting you cache assets and API responses with custom strategies (cache-first, network-first, stale-while-revalidate), serving them instantly on repeat visits or even without a network connection.', 'Funciona como un proxy de red dentro del navegador, permitiendo cachear assets y respuestas de API con estrategias personalizadas (cache-first, network-first, stale-while-revalidate), sirviéndolos al instante en visitas repetidas o incluso sin conexión de red.'),
    ('Service workers and caching', 'Service workers replace the need for a backend server entirely.', 'Los service workers eliminan por completo la necesidad de un servidor backend.'),
    ('Service workers and caching', 'Service workers can only cache HTML documents, not other asset types.', 'Los service workers solo pueden cachear documentos HTML, no otros tipos de asset.'),
    ('Layout thrashing', 'Repeatedly interleaving DOM reads (like offsetHeight) and writes (like style changes) in a loop forces the browser to recalculate layout synchronously on every iteration; batching all reads first, then all writes, avoids the repeated forced reflows.', 'Ir alternando repetidamente lecturas del DOM (como offsetHeight) y escrituras (como cambios de estilo) dentro de un bucle obliga al navegador a recalcular el layout de forma síncrona en cada iteración; agrupar primero todas las lecturas y luego todas las escrituras evita esos reflows forzados repetidos.'),
    ('Layout thrashing', 'Layout thrashing is caused exclusively by using too many CSS classes.', 'El layout thrashing lo causa exclusivamente usar demasiadas clases CSS.'),
    ('Layout thrashing', 'It only happens when animations are implemented with JavaScript, never CSS.', 'Solo ocurre cuando las animaciones se implementan con JavaScript, nunca con CSS.'),
    ('Font loading strategies', 'It controls how a web font is shown while it''s still loading (e.g. swap shows fallback text immediately then swaps to the custom font), preventing invisible text (FOIT) from blocking content from being seen.', 'Controla cómo se muestra una fuente web mientras todavía se está cargando (p. ej. swap muestra el texto de reserva de inmediato y luego lo cambia por la fuente personalizada), evitando que el texto invisible (FOIT) impida ver el contenido.'),
    ('Font loading strategies', 'font-display controls the font''s file size on disk.', 'font-display controla el tamaño en disco del archivo de la fuente.'),
    ('Font loading strategies', 'It only affects which font weights are available, not loading behavior.', 'Solo afecta a qué pesos de fuente están disponibles, no al comportamiento de carga.'),
    ('Time to First Byte', 'The time between the client''s request and the first byte of the server''s response arriving, affected by network latency, server processing time (like slow database queries), and any redirects along the way.', 'El tiempo entre la petición del cliente y la llegada del primer byte de la respuesta del servidor, afectado por la latencia de red, el tiempo de procesamiento del servidor (como consultas lentas a la base de datos) y cualquier redirección por el camino.'),
    ('Time to First Byte', 'TTFB measures how long it takes all images on the page to finish loading.', 'TTFB mide cuánto tardan en terminar de cargarse todas las imágenes de la página.'),
    ('Time to First Byte', 'TTFB is entirely determined by the client''s CPU speed, not the server.', 'TTFB lo determina por completo la velocidad de CPU del cliente, no el servidor.'),
    ('Resource hints', 'dns-prefetch resolves a domain''s DNS ahead of time; preconnect goes further and also establishes the TCP/TLS connection early — both reduce the latency of a later request to that origin by doing setup work before it''s actually needed.', 'dns-prefetch resuelve por adelantado el DNS de un dominio; preconnect va más allá y también establece pronto la conexión TCP/TLS; ambos reducen la latencia de una petición posterior a ese origen adelantando trabajo antes de que realmente haga falta.'),
    ('Resource hints', 'They immediately download the full content of a linked page in the background.', 'Descargan de inmediato en segundo plano todo el contenido de una página enlazada.'),
    ('Resource hints', 'These hints only work for same-origin requests, not third-party domains.', 'Estas pistas solo funcionan para peticiones del mismo origen, no para dominios de terceros.'),
    ('Reducing JS execution time', 'Code-split and lazy-load non-critical JS, remove unused code (tree shaking), avoid large synchronous work on the main thread (offload to Web Workers when possible), and minimize expensive re-renders in UI frameworks.', 'Dividir el código y cargar de forma diferida el JS no crítico, eliminar código sin usar (tree shaking), evitar trabajo síncrono grande en el hilo principal (delegándolo a Web Workers cuando sea posible), y minimizar los re-renders costosos en los frameworks de UI.'),
    ('Reducing JS execution time', 'Execution time can only be reduced by upgrading the user''s hardware.', 'El tiempo de ejecución solo se puede reducir mejorando el hardware del usuario.'),
    ('Reducing JS execution time', 'Minification alone eliminates all JavaScript execution time on the main thread.', 'La minificación por sí sola elimina todo el tiempo de ejecución de JavaScript en el hilo principal.'),
    ('Performance API', 'Measuring precise timing of custom events and built-in metrics (navigation timing, resource timing, Core Web Vitals like LCP/CLS) directly in the browser, enabling real-user monitoring (RUM) rather than only synthetic lab tests.', 'Medir con precisión el tiempo de eventos personalizados y de métricas integradas (navigation timing, resource timing, Core Web Vitals como LCP/CLS) directamente en el navegador, permitiendo monitorización de usuarios reales (RUM) y no solo pruebas sintéticas de laboratorio.'),
    ('Performance API', 'It can only measure CPU temperature on the client''s device.', 'Solo puede medir la temperatura de la CPU en el dispositivo del cliente.'),
    ('Performance API', 'The Performance API requires a paid third-party service to function.', 'La Performance API necesita un servicio de pago de terceros para funcionar.')
) AS v(q_title, text, text_es)
INNER JOIN questions q2 ON q2.title = v.q_title
WHERE o.question_id = q2.id AND o.text = v.text;
